import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes an image and returns a search query string.
 */
export async function analyzeImageForSearch(base64Data: string, mimeType: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Identify the main object in this image and provide a short, precise 2-4 word search query to find similar items in a classifieds marketplace. Return ONLY the search query text, no explanations." }
        ]
      }
    });

    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Image Analysis Error:", error);
    throw new Error("Failed to analyze image");
  }
}

/**
 * Generates a creative description for a classified ad.
 */
export async function generateAdDescription(title: string, categoryName: string, condition: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a compelling, professional, and attractive classified ad description for a ${categoryName} item titled "${title}" which is in "${condition}" condition. 
      Keep it under 100 words. Highlight potential benefits to a buyer. Do not include placeholders.`
    });
    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Description Gen Error:", error);
    return "Great item in good condition. Contact for more details.";
  }
}

/**
 * Suggests a price range for an item.
 */
export async function suggestPriceRange(title: string, categoryName: string, condition: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Estimate a realistic market price range (in USD) for a used "${title}" (${categoryName}) in "${condition}" condition. 
      Return ONLY the price range (e.g., "$150 - $200"). Do not add any conversational text.`
    });
    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Price Est Error:", error);
    return "$0 - $100";
  }
}

/**
 * Drafts a message to a seller.
 */
export async function draftBuyerMessage(intent: string, itemTitle: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Draft a polite and concise message to a seller regarding their item "${itemTitle}". 
      The buyer's intent is: "${intent}". Keep it informal but professional.`
    });
    return response.text?.trim() || "";
  } catch (error) {
    return `Hi, is ${itemTitle} still available?`;
  }
}

import { Listing } from '../types';

const LOCATIONS = ['New York, NY', 'Los Angeles, CA', 'Chicago, IL', 'Houston, TX', 'Phoenix, AZ', 'London, UK', 'Toronto, CA', 'Sydney, AU'];

export const generateListings = (categoryId: string, count: number = 6): Listing[] => {
  return Array.from({ length: count }).map((_, i) => {
    // Generate a consistent pseudo-random based on category and index
    const seed = categoryId.length + i * 123; 

    return {
      id: `${categoryId}-${i}`,
      title: `${categoryId.charAt(0).toUpperCase() + categoryId.slice(1).replace('-', ' ')} Item ${i + 1} - Great Condition`,
      price: Math.floor(Math.random() * 5000) + 50,
      currency: '$',
      location: LOCATIONS[i % LOCATIONS.length],
      imageUrl: `https://picsum.photos/seed/${seed}/400/300`,
      categoryId: categoryId,
      isFeatured: i === 0, // First one is featured
      datePosted: `${Math.floor(Math.random() * 5) + 1} days ago`
    };
  });
};

export const getAllFeatured = (categories: any[]): Listing[] => {
    const featured: Listing[] = [];
    categories.slice(0, 4).forEach(cat => {
        featured.push(...generateListings(cat.id, 1));
    });
    return featured;
}

export const getListingById = (id: string): Listing | undefined => {
  const parts = id.split('-');
  if (parts.length < 2) return undefined;

  // Reconstruct category from ID parts (handling categories with hyphens)
  // The logic in generateListings uses `${categoryId}-${i}`. 
  // We need to assume the last part is the index.
  const index = parseInt(parts[parts.length - 1]);
  const categoryId = parts.slice(0, parts.length - 1).join('-');

  if (isNaN(index)) return undefined;

  // We can just regenerate a small batch for that category and pick the right index
  // This ensures data consistency with the listing page
  const listings = generateListings(categoryId, index + 2);
  return listings[index];
}

