/**
 * Detects the user's location using Browser Geolocation (GPS) with a fallback to IP-based location.
 */
export async function detectUserLocation(): Promise<string> {
  // 1. Try Browser Geolocation (GPS)
  try {
    if ("geolocation" in navigator) {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, { 
          timeout: 5000,
          enableHighAccuracy: true 
        });
      });

      const { latitude, longitude } = position.coords;

      // Reverse Geocode using a free public API (BigDataCloud)
      // Note: In production, you might want to use Google Maps Geocoding API or similar with an API Key.
      const response = await fetch(
        `https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${latitude}&longitude=${longitude}&localityLanguage=en`
      );

      if (response.ok) {
        const data = await response.json();
        const city = data.city || data.locality || data.principalSubdivision;
        const country = data.countryName;
        if (city && country) {
          return `${city}, ${country}`;
        }
      }
    }
  } catch (error) {
    console.warn("GPS Location failed or denied, falling back to IP detection.", error);
  }

  // 2. Fallback to IP-based Geolocation
  try {
    const response = await fetch('https://ipapi.co/json/');
    if (response.ok) {
      const data = await response.json();
      if (data.city && data.country_name) {
        return `${data.city}, ${data.country_name}`;
      }
    }
  } catch (error) {
    console.error("IP Location detection failed.", error);
  }

  return "";
}

