/**
 * Detects the user's location using Browser Geolocation (GPS) with a fallback to IP-based location.
 */
export async function detectUserLocation(): Promise<string> {
  // 1. Try Browser Geolocation (GPS)
  try {
    if ("geolocation" in navigator) {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, { 
          timeout: 5000,
          enableHighAccuracy: true 
        });
      });

      const { latitude, longitude } = position.coords;

      // Reverse Geocode using a free public API (BigDataCloud)
      const response = await fetch(
        `https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${latitude}&longitude=${longitude}&localityLanguage=en`
      );

      if (response.ok) {
        const data = await response.json();
        const city = data.city || data.locality || data.principalSubdivision;
        const country = data.countryName;
        if (city && country) {
          return `${city}, ${country}`;
        }
      }
    }
  } catch (error) {
    // GPS failed or denied, proceed to IP
  }

  // 2. Fallback to IP-based Geolocation
  // Trying ipwho.is first as it is CORS friendly and free
  try {
    const response = await fetch('https://ipwho.is/');
    if (response.ok) {
      const data = await response.json();
      if (data.success && data.city && data.country) {
        return `${data.city}, ${data.country}`;
      }
    }
  } catch (error) {
    // Silent fail for first IP provider
  }

  // 3. Last resort fallback
  try {
    const response = await fetch('https://ipapi.co/json/');
    if (response.ok) {
      const data = await response.json();
      if (data.city && data.country_name) {
        return `${data.city}, ${data.country_name}`;
      }
    }
  } catch (error) {
    console.warn("Location detection failed.");
  }

  return "";
}

import { Listing } from '../types';

const LOCATIONS = ['New York, NY', 'Los Angeles, CA', 'Chicago, IL', 'Houston, TX', 'Phoenix, AZ', 'London, UK', 'Toronto, CA', 'Sydney, AU'];

export const generateListings = (categoryId: string, count: number = 6): Listing[] => {
  return Array.from({ length: count }).map((_, i) => {
    // Generate a consistent pseudo-random based on category and index
    const seed = categoryId.length + i * 123; 

    return {
      id: `${categoryId}-${i}`,
      title: `${categoryId.charAt(0).toUpperCase() + categoryId.slice(1).replace('-', ' ')} Item ${i + 1} - Great Condition`,
      price: Math.floor(Math.random() * 5000) + 50,
      currency: '$',
      location: LOCATIONS[i % LOCATIONS.length],
      imageUrl: `https://picsum.photos/seed/${seed}/400/300`,
      categoryId: categoryId,
      isFeatured: i === 0, // First one is featured
      datePosted: `${Math.floor(Math.random() * 5) + 1} days ago`
    };
  });
};

export const getAllFeatured = (categories: any[]): Listing[] => {
    const featured: Listing[] = [];
    // Get more items to fill the 5-column grid (e.g., 10 items)
    categories.slice(0, 10).forEach(cat => {
        featured.push(...generateListings(cat.id, 1));
    });
    return featured;
}

export const getListingById = (id: string): Listing | undefined => {
  const parts = id.split('-');
  if (parts.length < 2) return undefined;

  // Reconstruct category from ID parts (handling categories with hyphens)
  // The logic in generateListings uses `${categoryId}-${i}`. 
  // We need to assume the last part is the index.
  const index = parseInt(parts[parts.length - 1]);
  const categoryId = parts.slice(0, parts.length - 1).join('-');

  if (isNaN(index)) return undefined;

  // We can just regenerate a small batch for that category and pick the right index
  // This ensures data consistency with the listing page
  const listings = generateListings(categoryId, index + 2);
  return listings[index];
}

