import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes an image and returns a search query string.
 */
export async function analyzeImageForSearch(base64Data: string, mimeType: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Analyze this image and identify the main item for sale. Generate a short, precise search query (2-5 words) that I can use to find this item on a classifieds website. Examples: 'iPhone 14 Pro Max', 'Wooden Dining Table', 'Red Mountain Bike'. Return ONLY the search query text." }
        ]
      },
      config: {
        temperature: 0.1, // Low temperature for deterministic results
      }
    });

    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Image Analysis Error:", error);
    throw new Error("Failed to analyze image");
  }
}

/**
 * Generates a creative description for a classified ad.
 */
export async function generateAdDescription(title: string, categoryName: string, condition: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a compelling, professional, and attractive classified ad description for a ${categoryName} item titled "${title}" which is in "${condition}" condition. 
      Keep it under 100 words. Highlight potential benefits to a buyer. Do not include placeholders.`,
      config: {
        temperature: 0.7, // Higher temperature for creativity
      }
    });
    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Description Gen Error:", error);
    return "Great item in good condition. Contact for more details.";
  }
}

/**
 * Suggests a price range for an item.
 */
export async function suggestPriceRange(title: string, categoryName: string, condition: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Estimate a realistic market price range (in USD) for a used "${title}" (${categoryName}) in "${condition}" condition. 
      Return ONLY the price range (e.g., "$150 - $200"). Do not add any conversational text.`,
      config: {
        temperature: 0.2,
      }
    });
    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Price Est Error:", error);
    return "$0 - $100";
  }
}

/**
 * Drafts a message to a seller.
 */
export async function draftBuyerMessage(intent: string, itemTitle: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Draft a polite and concise message to a seller regarding their item "${itemTitle}". 
      The buyer's intent is: "${intent}". Keep it informal but professional.`,
      config: {
        temperature: 0.5,
      }
    });
    return response.text?.trim() || "";
  } catch (error) {
    return `Hi, is ${itemTitle} still available?`;
  }
}

import React, { useState, useRef } from 'react';
import Icon from './Icon';
import { analyzeImageForSearch } from '../services/ai';

interface SmartSearchInputProps {
  placeholder?: string;
  className?: string;
  onSearch?: (query: string) => void;
  variant?: 'simple' | 'hero';
}

const SmartSearchInput: React.FC<SmartSearchInputProps> = ({ 
  placeholder = "Search...", 
  className = "", 
  onSearch,
  variant = 'simple'
}) => {
  const [query, setQuery] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleVoiceSearch = () => {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      alert("Voice search is not supported in your browser.");
      return;
    }

    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setQuery(transcript);
      if (onSearch) onSearch(transcript);
    };

    recognition.start();
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Validation: 5MB Limit
    if (file.size > 5 * 1024 * 1024) {
      alert("Image size is too large. Please upload an image under 5MB.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsAnalyzing(true);
    const reader = new FileReader();

    reader.onloadend = async () => {
      try {
        const base64String = (reader.result as string).split(',')[1];
        const result = await analyzeImageForSearch(base64String, file.type);
        setQuery(result);
        if (onSearch) onSearch(result);
      } catch (error) {
        console.error(error);
        alert("Failed to analyze image. Please try again.");
      } finally {
        setIsAnalyzing(false);
        // Reset file input so same file can be selected again if needed
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsDataURL(file);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && onSearch) {
      onSearch(query);
    }
  };

  return (
    <div className={`relative flex items-center ${className}`}>
      {variant === 'simple' && (
        <div className="absolute left-3 text-slate-400">
           <Icon name="search" size={18} />
        </div>
      )}

      <input 
        type="text" 
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        disabled={isAnalyzing}
        className={`w-full bg-transparent focus:outline-none transition-all ${
           variant === 'simple' 
             ? 'pl-10 pr-20 py-2.5 rounded-full border border-slate-300 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-brand-500 focus:border-transparent' 
             : 'text-slate-800 placeholder-slate-400'
        } ${isAnalyzing ? 'opacity-50 cursor-wait' : ''}`}
      />

      <div className={`absolute flex items-center gap-1 ${variant === 'simple' ? 'right-2' : 'right-0'}`}>
        {isAnalyzing ? (
          <div className="flex items-center gap-2 px-2">
            <span className="text-xs text-brand-600 font-medium whitespace-nowrap hidden sm:block">Thinking...</span>
            <div className="animate-spin text-brand-500">
              <Icon name="loader" size={20} />
            </div>
          </div>
        ) : (
          <>
             <button 
               onClick={() => fileInputRef.current?.click()}
               className="p-2 text-slate-400 hover:text-brand-600 hover:bg-slate-100 rounded-full transition-colors group relative"
               title="Search by Image"
             >
               <Icon name="camera" size={20} />
               <span className="absolute -top-8 left-1/2 -translate-x-1/2 bg-slate-800 text-white text-[10px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">Image Search</span>
             </button>
             <button 
               onClick={handleVoiceSearch}
               className={`p-2 rounded-full transition-colors ${isListening ? 'text-red-500 bg-red-50 animate-pulse' : 'text-slate-400 hover:text-brand-600 hover:bg-slate-100'}`}
               title="Voice Search"
             >
               <Icon name="mic" size={20} />
             </button>
          </>
        )}
      </div>

      <input 
        type="file" 
        ref={fileInputRef}
        onChange={handleImageUpload}
        accept="image/*"
        className="hidden" 
      />
    </div>
  );
};

export default SmartSearchInput;

