import React, { useState, useRef } from 'react';
import Icon from './Icon';
import { analyzeImageForSearch } from '../services/ai';
import { CATEGORIES } from '../constants';
import { SearchFilters } from '../types';

interface SmartSearchInputProps {
  placeholder?: string;
  className?: string;
  onSearch?: (query: string, filters?: SearchFilters) => void;
  variant?: 'simple' | 'hero';
}

const SmartSearchInput: React.FC<SmartSearchInputProps> = ({ 
  placeholder = "Search...", 
  className = "", 
  onSearch,
  variant = 'simple'
}) => {
  const [query, setQuery] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showFilters, setShowFilters] = useState(false);

  // Filter States
  const [filters, setFilters] = useState<SearchFilters>({
    categoryId: '',
    minPrice: '',
    maxPrice: '',
    location: '',
    condition: '',
    sortBy: 'newest'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleVoiceSearch = () => {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      alert("Voice search is not supported in your browser.");
      return;
    }

    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setQuery(transcript);
      if (onSearch) onSearch(transcript, filters);
    };

    recognition.start();
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
      alert("Image size is too large. Please upload an image under 5MB.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsAnalyzing(true);
    const reader = new FileReader();

    reader.onloadend = async () => {
      try {
        const base64String = (reader.result as string).split(',')[1];
        const result = await analyzeImageForSearch(base64String, file.type);
        setQuery(result);
        if (onSearch) onSearch(result, filters);
      } catch (error) {
        console.error(error);
        alert("Failed to analyze image. Please try again.");
      } finally {
        setIsAnalyzing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsDataURL(file);
  };

  const handleFilterChange = (field: keyof SearchFilters, value: string) => {
    setFilters(prev => ({ ...prev, [field]: value }));
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && onSearch) {
      onSearch(query, filters);
      setShowFilters(false);
    }
  };

  const handleApplyFilters = () => {
    if (onSearch) {
      onSearch(query, filters);
    }
    setShowFilters(false);
  };

  return (
    <div className={`relative ${className}`}>
      <div className="relative flex items-center z-20">
        {variant === 'simple' && (
          <div className="absolute left-3 text-slate-400 pointer-events-none">
             <Icon name="search" size={18} />
          </div>
        )}

        <input 
          type="text" 
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          disabled={isAnalyzing}
          className={`w-full bg-transparent focus:outline-none transition-all ${
             variant === 'simple' 
               ? 'pl-10 pr-32 py-2.5 rounded-full border border-slate-300 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-brand-500 focus:border-transparent' 
               : 'text-slate-800 placeholder-slate-400 pr-24'
          } ${isAnalyzing ? 'opacity-50 cursor-wait' : ''}`}
        />

        <div className={`absolute flex items-center gap-1 ${variant === 'simple' ? 'right-2' : 'right-0'}`}>
          {isAnalyzing ? (
            <div className="flex items-center gap-2 px-2">
              <span className="text-xs text-brand-600 font-medium whitespace-nowrap hidden sm:block">Thinking...</span>
              <div className="animate-spin text-brand-500">
                <Icon name="loader" size={20} />
              </div>
            </div>
          ) : (
            <>
               <button 
                 onClick={() => setShowFilters(!showFilters)}
                 className={`p-2 rounded-full transition-colors relative ${showFilters ? 'text-brand-600 bg-brand-50' : 'text-slate-400 hover:text-brand-600 hover:bg-slate-100'}`}
                 title="Advanced Filters"
               >
                 <Icon name="sliders" size={18} />
               </button>
               <div className="w-px h-5 bg-slate-300 mx-1"></div>
               <button 
                 onClick={() => fileInputRef.current?.click()}
                 className="p-2 text-slate-400 hover:text-brand-600 hover:bg-slate-100 rounded-full transition-colors group relative"
                 title="Search by Image"
               >
                 <Icon name="camera" size={20} />
               </button>
               <button 
                 onClick={handleVoiceSearch}
                 className={`p-2 rounded-full transition-colors ${isListening ? 'text-red-500 bg-red-50 animate-pulse' : 'text-slate-400 hover:text-brand-600 hover:bg-slate-100'}`}
                 title="Voice Search"
               >
                 <Icon name="mic" size={20} />
               </button>
            </>
          )}
        </div>

        <input 
          type="file" 
          ref={fileInputRef}
          onChange={handleImageUpload}
          accept="image/*"
          className="hidden" 
        />
      </div>

      {/* Advanced Filters Dropdown */}
      {showFilters && (
        <>
          {/* Overlay to close on click outside */}
          <div className="fixed inset-0 z-40" onClick={() => setShowFilters(false)}></div>

          <div className={`absolute top-full right-0 mt-3 w-full sm:w-[400px] bg-white/90 backdrop-blur-xl border border-white/50 rounded-2xl shadow-[0_20px_40px_-10px_rgba(0,0,0,0.1)] p-5 z-50 animate-fade-in ${variant === 'simple' ? 'left-0 sm:left-auto' : 'left-0'}`}>
            <div className="flex justify-between items-center mb-4">
               <h3 className="font-bold text-slate-800 flex items-center gap-2">
                 <Icon name="sliders" size={16} className="text-brand-600" /> Filter Options
               </h3>
               <button onClick={() => setFilters({ categoryId: '', minPrice: '', maxPrice: '', location: '', condition: '', sortBy: 'newest' })} className="text-xs text-brand-600 hover:underline">
                 Reset
               </button>
            </div>

            <div className="space-y-4">
              {/* Category */}
              <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1">Category</label>
                <select 
                  value={filters.categoryId} 
                  onChange={(e) => handleFilterChange('categoryId', e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500"
                >
                  <option value="">All Categories</option>
                  {CATEGORIES.map(cat => (
                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                  ))}
                </select>
              </div>

              {/* Price Range */}
              <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1">Price Range</label>
                <div className="flex gap-2">
                  <input 
                    type="number" 
                    placeholder="Min" 
                    value={filters.minPrice}
                    onChange={(e) => handleFilterChange('minPrice', e.target.value)}
                    className="w-1/2 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500"
                  />
                  <input 
                    type="number" 
                    placeholder="Max" 
                    value={filters.maxPrice}
                    onChange={(e) => handleFilterChange('maxPrice', e.target.value)}
                    className="w-1/2 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500"
                  />
                </div>
              </div>

              {/* Location & Condition Row */}
              <div className="grid grid-cols-2 gap-3">
                 <div>
                    <label className="block text-xs font-semibold text-slate-500 mb-1">Location</label>
                    <div className="relative">
                      <input 
                        type="text" 
                        placeholder="City or Zip" 
                        value={filters.location}
                        onChange={(e) => handleFilterChange('location', e.target.value)}
                        className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 pl-7 text-sm outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500"
                      />
                      <div className="absolute left-2 top-2 text-slate-400">
                        <Icon name="mapPin" size={12} />
                      </div>
                    </div>
                 </div>
                 <div>
                    <label className="block text-xs font-semibold text-slate-500 mb-1">Condition</label>
                    <select 
                      value={filters.condition} 
                      onChange={(e) => handleFilterChange('condition', e.target.value)}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500"
                    >
                      <option value="">Any</option>
                      <option value="new">New</option>
                      <option value="used-like-new">Used - Like New</option>
                      <option value="used-good">Used - Good</option>
                      <option value="used-fair">Used - Fair</option>
                    </select>
                 </div>
              </div>

              <div className="pt-2">
                <button 
                  onClick={handleApplyFilters}
                  className="w-full bg-brand-600 text-white font-semibold py-2.5 rounded-xl hover:bg-brand-700 transition-colors shadow-lg shadow-brand-500/20"
                >
                  Apply Filters
                </button>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

