  const [isLocating, setIsLocating] = useState(false);

  useEffect(() => {
    const fetchLocation = async () => {
      setIsLocating(true);
      const loc = await detectUserLocation();
      if (loc) {
        setLocation(loc);
      }
      setIsLocating(false);
    };

    fetchLocation();
  }, []);

  const handleManualLocate = async () => {
    setIsLocating(true);
