export const generateListings = (categoryId: string, count: number = 6, startIndex: number = 0): Listing[] => {
  return Array.from({ length: count }).map((_, i) => {
    const currentIndex = startIndex + i;
    const seed = categoryId.length + currentIndex * 123; 

    // Assign a random seller (excluding 'user-me')
    const seller = USERS[Math.floor(Math.random() * (USERS.length - 1))];

    return {
      id: `${categoryId}-${currentIndex}`,
      title: `${categoryId.charAt(0).toUpperCase() + categoryId.slice(1).replace('-', ' ')} Item ${currentIndex + 1} - Great Condition`,
      price: Math.floor(Math.random() * 5000) + 50,
      currency: '$',
      location: LOCATIONS[currentIndex % LOCATIONS.length],
      imageUrl: `https://picsum.photos/seed/${seed}/400/300`,
      categoryId: categoryId,
      isFeatured: false,
      datePosted: `${Math.floor(Math.random() * 5) + 1} days ago`,
      sellerId: seller.id
    };
  });
};

