export const getChatsForUser = (userId: string): Chat[] => {
  return CHATS.filter(c => c.participants.includes(userId));
};

export const getChat = (chatId: string): Chat | undefined => {
  return CHATS.find(c => c.id === chatId);
};

export const createChat = (myId: string, otherUserId: string, listingId?: string): string => {
  // Check if chat already exists
  const existing = CHATS.find(c => c.participants.includes(myId) && c.participants.includes(otherUserId));
  if (existing) return existing.id;

  const newChat: Chat = {
    id: `chat-${Date.now()}`,
    participants: [myId, otherUserId],
    listingId,
    messages: [],
    lastMessage: 'Started a new conversation',
    lastMessageTime: 'Just now',
    unreadCount: 0
  };

  CHATS = [newChat, ...CHATS];
  return newChat.id;
};

export const sendMessage = (chatId: string, senderId: string, text: string) => {
  const chatIndex = CHATS.findIndex(c => c.id === chatId);
  if (chatIndex > -1) {
    const newMessage: ChatMessage = {
      id: `msg-${Date.now()}`,
      senderId,
      text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isRead: false
    };

    // Update Chat
    const chat = { ...CHATS[chatIndex] };
    chat.messages = [...chat.messages, newMessage];
    chat.lastMessage = text;
    chat.lastMessageTime = 'Just now';

    // Move to top
    CHATS.splice(chatIndex, 1);
    CHATS = [chat, ...CHATS];
    return chat;
  }
};

