import React, { createContext, useContext, useState, useEffect } from 'react';
import { User } from '../types';
import { getUser } from '../services/mockData';

interface AuthContextType {
  user: User | null;
  login: () => void;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  // Check local storage on mount to persist session
  useEffect(() => {
    const storedUserId = localStorage.getItem('tym2muv_user_id');
    if (storedUserId) {
      const foundUser = getUser(storedUserId);
      if (foundUser) setUser(foundUser);
    }
  }, []);

  const login = () => {
    // Simulating login as the mock "user-me"
    const mockUser = getUser('user-me');
    if (mockUser) {
      setUser(mockUser);
      localStorage.setItem('tym2muv_user_id', 'user-me');
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('tym2muv_user_id');
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, isAuthenticated: !!user }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

interface ProtectedRouteProps {
  children: React.ReactNode;
}

const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children }) => {
  const { isAuthenticated } = useAuth();
  const location = useLocation();

  if (!isAuthenticated) {
    // Redirect to the sign-in page, but save the current location they were trying to go to
    return <Navigate to="/signin" state={{ from: location }} replace />;
  }

  return <>{children}</>;
};

export default ProtectedRoute;

