                             Condition?
                          </button>
                       </div>

                       <textarea 
                          value={message}
                          onChange={(e) => setMessage(e.target.value)}
                          className={`w-full p-3 rounded-lg border text-sm focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none resize-none ${isAiDrafting ? 'bg-slate-100 animate-pulse' : 'bg-white border-slate-200'}`}
