import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getUser, getUserListings } from '../services/mockData';
import { User, Listing } from '../types';
import ListingCard from '../components/ListingCard';
import Icon from '../components/Icon';

const Profile: React.FC = () => {
  const { userId } = useParams<{ userId: string }>();
  const [user, setUser] = useState<User | undefined>(undefined);
  const [listings, setListings] = useState<Listing[]>([]);
  const [activeTab, setActiveTab] = useState('listings');

  useEffect(() => {
    // Scroll to top on mount
    window.scrollTo(0, 0);

    if (userId) {
      const idToFetch = userId === 'me' ? 'user-me' : userId;
      const u = getUser(idToFetch);
      setUser(u);
      if (u) {
          setListings(getUserListings(u.id));
      }
    }
  }, [userId]);

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: `Check out ${user?.name}'s profile on tym2muv`,
        url: window.location.href
      }).catch(console.error);
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Profile link copied to clipboard!');
    }
  };

  if (!user) {
    return (
        <div className="flex flex-col items-center justify-center min-h-[60vh] animate-fade-in">
            <div className="animate-spin text-brand-500 mb-4"><Icon name="loader" size={40} /></div>
            <p className="text-slate-500 font-medium">Finding user profile...</p>
