import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { CATEGORIES } from '../constants';
import ListingCard from '../components/ListingCard';
import { generateListings } from '../services/mockData';
import Icon from '../components/Icon';

const ITEMS_PER_BATCH = 40; // 8 rows * 5 columns = 40 items

const CategoryPage: React.FC = () => {
  const { categoryId } = useParams<{ categoryId: string }>();
  const [activeSub, setActiveSub] = useState<string | null>(null);
  const [listings, setListings] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const category = CATEGORIES.find(c => c.id === categoryId);

  // Reset and load initial batch when category changes
  useEffect(() => {
    if (categoryId) {
      const initialListings = generateListings(categoryId, ITEMS_PER_BATCH, 0);
      setListings(initialListings);
    }
  }, [categoryId]);

  const handleLoadMore = () => {
    if (!categoryId) return;

    setIsLoading(true);
    // Simulate network delay for realistic feel
    setTimeout(() => {
      const nextBatch = generateListings(categoryId, ITEMS_PER_BATCH, listings.length);
      setListings(prev => [...prev, ...nextBatch]);
      setIsLoading(false);
    }, 800);
  };

  if (!category) {
    return (
      <div className="container mx-auto px-4 py-20 text-center">
        <h2 className="text-2xl font-bold text-slate-800">Category not found</h2>
        <Link to="/" className="text-brand-600 mt-4 inline-block">Go Home</Link>
      </div>
    );
  }

  return (
    <div className="bg-brand-50 min-h-screen pb-12">
      {/* Header Breadcrumb Area */}
      <div className="bg-white border-b border-slate-200">
        <div className="container mx-auto px-4 py-8">
           <div className="text-sm text-slate-500 mb-2 flex items-center gap-2">
              <Link to="/" className="hover:text-brand-600">Home</Link>
              <Icon name="chevronRight" size={14} />
              <span className="font-medium text-slate-900">{category.name}</span>
           </div>
           <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
              <div className={`p-2 rounded-lg ${category.color.replace('text-', 'bg-').replace('bg-', 'text-white ')} bg-opacity-90`}>
                 <Icon name={category.iconName} size={32} />
              </div>
              {category.name} Listings
           </h1>
        </div>
      </div>

      <div className="container mx-auto px-4 py-6">
        {/* Top Filters & Subcategories Section */}
        <div className="bg-white rounded-2xl p-4 md:p-6 shadow-sm border border-slate-200 mb-8 space-y-5">

           {/* Row 1: Subcategories Horizontal Scroll */}
           <div>
              <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Subcategories</h3>
              <div className="flex gap-2 overflow-x-auto custom-scrollbar pb-2 snap-x">
                 <button 
                    onClick={() => setActiveSub(null)}
                    className={`snap-start whitespace-nowrap px-4 py-2 rounded-full text-sm font-medium transition-all ${activeSub === null ? 'bg-brand-600 text-white shadow-md ring-2 ring-brand-100' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 hover:text-slate-900'}`}
                  >
                    All {category.name}
                  </button>
                  {category.subcategories.map(sub => (
                    <button 
                       key={sub.id}
                       onClick={() => setActiveSub(sub.id)}
                       className={`snap-start whitespace-nowrap px-4 py-2 rounded-full text-sm font-medium transition-all ${activeSub === sub.id ? 'bg-brand-600 text-white shadow-md ring-2 ring-brand-100' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 hover:text-slate-900'}`}
                    >
                      {sub.name}
                    </button>
                  ))}
              </div>
           </div>

           <div className="h-px bg-slate-100"></div>

           {/* Row 2: Filters & Sort */}
           <div className="flex flex-col md:flex-row gap-4 items-start md:items-center justify-between">

              {/* Price Filter */}
              <div className="flex items-center gap-3 w-full md:w-auto">
                 <span className="text-sm font-semibold text-slate-700 whitespace-nowrap flex items-center gap-1">
                    <Icon name="coins" size={14} /> Price Range:
                 </span>
                 <div className="flex gap-2 items-center flex-1 md:flex-none">
                    <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs">$</span>
                        <input type="number" placeholder="Min" className="w-full md:w-28 pl-6 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none transition-all" />
                    </div>
                    <span className="text-slate-400 font-medium">-</span>
                    <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs">$</span>
                        <input type="number" placeholder="Max" className="w-full md:w-28 pl-6 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:border-brand-500 focus:ring-2 focus:ring-brand-100 outline-none transition-all" />
                    </div>
                 </div>
              </div>

              {/* Sort Dropdown */}
              <div className="flex items-center gap-3 w-full md:w-auto justify-end">
                 <span className="text-sm font-semibold text-slate-700 whitespace-nowrap">Sort by:</span>
                 <div className="relative w-full md:w-48">
                    <select className="appearance-none w-full border border-slate-300 rounded-lg px-4 py-2 pr-8 text-sm bg-white focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none cursor-pointer">
                        <option>Newest First</option>
                        <option>Price: Low to High</option>
                        <option>Price: High to Low</option>
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                        <Icon name="chevronRight" size={12} className="rotate-90" />
                    </div>
                 </div>
              </div>
           </div>
        </div>

        {/* Listings Section */}
        <div className="flex justify-between items-center mb-4 px-2">
           <p className="text-slate-500 font-medium text-sm">Showing {listings.length} results</p>
        </div>

        {/* Grid 5 per row, gap reduced */}
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-5 gap-3 sm:gap-4">
           {listings.map(listing => (
              <ListingCard key={listing.id} listing={listing} />
           ))}
        </div>

        {/* Load More Button */}
        <div className="mt-12 flex justify-center">
           <button 
             onClick={handleLoadMore}
             disabled={isLoading}
             className="flex items-center gap-2 px-8 py-3 bg-white border border-slate-300 rounded-xl hover:bg-slate-50 text-slate-700 font-bold shadow-sm hover:shadow-md transition-all disabled:opacity-70 disabled:cursor-not-allowed group"
           >
             {isLoading ? (
               <>
                 <span className="w-4 h-4 border-2 border-slate-400 border-t-brand-600 rounded-full animate-spin"></span>
                 Loading...
               </>
             ) : (
               <>
                 Load More Results
                 <Icon name="chevronRight" size={14} className="rotate-90 group-hover:translate-y-0.5 transition-transform" />
               </>
             )}
           </button>
        </div>
      </div>
    </div>
  );
};

export default CategoryPage;

