import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes an image and returns a search query string.
 */
export async function analyzeImageForSearch(base64Data: string, mimeType: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Analyze this image and identify the main item for sale. Generate a short, precise search query (2-5 words) that I can use to find this item on a classifieds website. Examples: 'iPhone 14 Pro Max', 'Wooden Dining Table', 'Red Mountain Bike'. Return ONLY the search query text." }
        ]
      },
      config: {
        temperature: 0.1, // Low temperature for deterministic results
      }
    });

    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Image Analysis Error:", error);
    throw new Error("Failed to analyze image");
  }
}

/**
 * Generates a creative description for a classified ad.
 */
export async function generateAdDescription(title: string, categoryName: string, condition: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a compelling, professional, and attractive classified ad description for a ${categoryName} item titled "${title}" which is in "${condition}" condition. 
      Keep it under 100 words. Highlight potential benefits to a buyer. Do not include placeholders.`,
      config: {
        temperature: 0.7, // Higher temperature for creativity
      }
    });
    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Description Gen Error:", error);
    return "Great item in good condition. Contact for more details.";
  }
}

/**
 * Suggests a price range for an item.
 */
export async function suggestPriceRange(title: string, categoryName: string, condition: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Estimate a realistic market price range (in USD) for a used "${title}" (${categoryName}) in "${condition}" condition. 
      Return ONLY the price range (e.g., "$150 - $200"). Do not add any conversational text.`,
      config: {
        temperature: 0.2,
      }
    });
    return response.text?.trim() || "";
  } catch (error) {
    console.error("Gemini Price Est Error:", error);
    return "$0 - $100";
  }
}

/**
 * Drafts a message to a seller.
 */
export async function draftBuyerMessage(intent: string, itemTitle: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Draft a polite and concise message to a seller regarding their item "${itemTitle}". 
      The buyer's intent is: "${intent}". Keep it informal but professional.`,
      config: {
        temperature: 0.5,
      }
    });
    return response.text?.trim() || "";
  } catch (error) {
    return `Hi, is ${itemTitle} still available?`;
  }
}

/**
 * Enhances an image using AI (Sharpness, Lighting).
 */
export async function enhanceImage(base64Data: string, mimeType: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Data
            }
          },
          { text: "Enhance the sharpness, lighting, clarity, and overall quality of this product image to make it look professional for a listing. Do not change the content." }
        ]
      },
    });

    // Extract image from response
    for (const candidate of response.candidates || []) {
        for (const part of candidate.content?.parts || []) {
            if (part.inlineData) {
                return part.inlineData.data;
            }
        }
    }
    throw new Error("No image generated");
  } catch (error) {
    console.error("Gemini Image Enhancement Error:", error);
    throw error;
  }
}

import React, { useState, useRef } from 'react';
import { CATEGORIES } from '../constants';
import Icon from '../components/Icon';
import { Link } from 'react-router-dom';
import { generateAdDescription, suggestPriceRange, enhanceImage } from '../services/ai';

const PostAd: React.FC = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    categoryId: '',
    categoryName: '',
    title: '',
    price: '',
    condition: 'Used - Good',
    description: ''
  });
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiPriceSuggestion, setAiPriceSuggestion] = useState('');

  // Image handling
  const [images, setImages] = useState<string[]>([]);
  const [enhancingIndices, setEnhancingIndices] = useState<number[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleCategorySelect = (id: string, name: string) => {
    setFormData(prev => ({ ...prev, categoryId: id, categoryName: name }));
    setStep(2);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleAiGenerate = async () => {
    if (!formData.title || !formData.categoryId) {
      alert("Please enter a title first!");
      return;
    }

    setIsAiLoading(true);
    try {
      const description = await generateAdDescription(formData.title, formData.categoryName, formData.condition);
      setFormData(prev => ({ ...prev, description }));

      const priceRange = await suggestPriceRange(formData.title, formData.categoryName, formData.condition);
      setAiPriceSuggestion(priceRange);
    } catch (error) {
      console.error(error);
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files = Array.from(e.target.files);

      files.forEach(file => {
        const reader = new FileReader();
        reader.onloadend = () => {
            if (reader.result) {
                setImages(prev => [...prev, reader.result as string]);
            }
        };
        // Explicitly cast to Blob to avoid TypeScript 'unknown' error
        reader.readAsDataURL(file as Blob);
      });
    }
  };

  const removeImage = (indexToRemove: number) => {
    setImages(prev => prev.filter((_, index) => index !== indexToRemove));
  };

  const handleEnhanceImage = async (index: number) => {
    if (enhancingIndices.includes(index)) return;

    const imageSrc = images[index];
    const matches = imageSrc.match(/^data:(.+);base64,(.+)$/);
    if (!matches) return;

    const mimeType = matches[1];
    const base64Data = matches[2];

    setEnhancingIndices(prev => [...prev, index]);

    try {
        const enhancedBase64 = await enhanceImage(base64Data, mimeType);
        const newImageSrc = `data:image/png;base64,${enhancedBase64}`;

        setImages(prev => {
            const newImages = [...prev];
            newImages[index] = newImageSrc;
            return newImages;
        });
    } catch (e) {
        alert("Failed to enhance image. Please try again.");
    } finally {
        setEnhancingIndices(prev => prev.filter(i => i !== index));
    }
  };

  return (
    <div className="container mx-auto px-4 py-12 max-w-4xl min-h-screen">
      <div className="text-center mb-10">
        <h1 className="text-4xl font-bold text-slate-900 mb-3">Sell it fast.</h1>
        <p className="text-slate-500 text-lg">Use our AI tools to create the perfect listing in seconds.</p>
      </div>

      <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
        {/* Progress Bar */}
        <div className="bg-slate-50/50 border-b border-slate-100 p-6 flex justify-between items-center px-4 md:px-12">
           <div className={`flex items-center gap-2 ${step >= 1 ? 'text-brand-600 font-semibold' : 'text-slate-400'}`}>
              <span className={`w-8 h-8 rounded-full border-2 flex items-center justify-center text-sm ${step >= 1 ? 'border-brand-600 bg-brand-50' : 'border-current'}`}>1</span>
              <span className="hidden sm:inline">Category</span>
           </div>
           <div className="h-[2px] bg-slate-200 flex-1 mx-4">
             <div className="h-full bg-brand-500 transition-all duration-300" style={{ width: step >= 2 ? '50%' : step >= 3 ? '100%' : '0%' }}></div>
           </div>
           <div className={`flex items-center gap-2 ${step >= 2 ? 'text-brand-600 font-semibold' : 'text-slate-400'}`}>
              <span className={`w-8 h-8 rounded-full border-2 flex items-center justify-center text-sm ${step >= 2 ? 'border-brand-600 bg-brand-50' : 'border-current'}`}>2</span>
              <span className="hidden sm:inline">Details</span>
           </div>
           <div className="h-[2px] bg-slate-200 flex-1 mx-4">
             <div className="h-full bg-brand-500 transition-all duration-300" style={{ width: step >= 3 ? '100%' : '0%' }}></div>
           </div>
           <div className={`flex items-center gap-2 ${step >= 3 ? 'text-brand-600 font-semibold' : 'text-slate-400'}`}>
              <span className={`w-8 h-8 rounded-full border-2 flex items-center justify-center text-sm ${step >= 3 ? 'border-brand-600 bg-brand-50' : 'border-current'}`}>3</span>
              <span className="hidden sm:inline">Photos</span>
           </div>
        </div>

        <div className="p-6 md:p-10">
          {step === 1 && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 animate-fade-in">
              {CATEGORIES.map(cat => (
