                 <p className="text-slate-500">Drag and drop or click to browse</p>
                 <p className="text-xs text-slate-400 mt-2 uppercase tracking-wider font-medium">Supports JPG, PNG</p>
                 <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    multiple 
                    accept="image/*"
                    onChange={handleImageUpload}
                 />
              </div>

              {/* Image Grid */}
              {images.length > 0 && (
                <div>
                    <h4 className="text-sm font-bold text-slate-700 mb-3">{images.length} Photos Selected</h4>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {images.map((img, index) => (
                            <div key={index} className="relative aspect-square rounded-2xl overflow-hidden group border border-slate-200 shadow-sm bg-slate-100">
                                <img src={img} alt={`Preview ${index}`} className="w-full h-full object-cover" />
                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors"></div>

                                {/* AI Enhance Button */}
                                <button 
                                    onClick={(e) => { e.stopPropagation(); handleEnhanceImage(index); }}
                                    className={`absolute top-2 left-2 p-1.5 rounded-full shadow-md transition-all z-20 ${enhancingIndices.includes(index) ? 'bg-white text-brand-500' : 'bg-white/90 text-brand-600 opacity-0 group-hover:opacity-100 hover:bg-white hover:scale-110'}`}
                                    title="Auto-Enhance Sharpness"
                                    disabled={enhancingIndices.includes(index)}
                                >
                                    {enhancingIndices.includes(index) ? (
                                        <Icon name="loader" size={16} className="animate-spin" />
                                    ) : (
                                        <Icon name="sparkles" size={16} />
                                    )}
                                </button>

                                <button 
                                    onClick={(e) => { e.stopPropagation(); removeImage(index); }}
                                    className="absolute top-2 right-2 p-1.5 bg-white text-red-500 rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-all hover:bg-red-50 hover:scale-110 z-20"
                                    title="Remove photo"
                                >
                                    <Icon name="x" size={16} />
                                </button>

                                {index === 0 && (
                                    <div className="absolute bottom-2 left-2 px-2 py-1 bg-black/60 backdrop-blur rounded text-[10px] text-white font-bold">
                                        COVER
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
              )}

               <div className="flex justify-between pt-8 border-t border-slate-100">
                  <button onClick={() => setStep(2)} className="text-slate-500 hover:text-slate-900 font-medium px-4 py-2">Back</button>
                  <Link to="/" className={`bg-brand-600 text-white px-10 py-4 rounded-xl font-bold hover:bg-brand-700 shadow-xl shadow-brand-500/30 transform hover:-translate-y-0.5 transition-all flex items-center gap-2 ${images.length === 0 ? 'opacity-50 pointer-events-none' : ''}`}>
                     <Icon name="check" size={20} /> Publish Ad
                  </Link>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

