  currency: string;
  symbol: string;
  formattedAddress: string;
}

/**
 * Detects the user's location and currency using IP-based geolocation.
 */
export async function detectUserLocation(): Promise<UserLocationData> {
  const fallback: UserLocationData = {
    city: 'New York',
    country: 'USA',
    currency: 'USD',
    symbol: '$',
    formattedAddress: 'New York, NY'
  };

  // 1. Try ipwho.is (CORS friendly, returns currency info)
  try {
    const response = await fetch('https://ipwho.is/');
    if (response.ok) {
      const data = await response.json();
      if (data.success) {
        return {
          city: data.city,
          country: data.country,
          currency: data.currency.code,
          symbol: data.currency.symbol,
          formattedAddress: `${data.city}, ${data.country_code}`
        };
      }
    }
  } catch (error) {
    console.warn("ipwho.is failed", error);
  }

  // 2. Fallback: ipapi.co
  try {
    const response = await fetch('https://ipapi.co/json/');
    if (response.ok) {
      const data = await response.json();
      return {
        city: data.city,
        country: data.country_name,
        currency: data.currency,
        symbol: getSymbolFromCode(data.currency),
        formattedAddress: `${data.city}, ${data.country_code}`
      };
    }
  } catch (error) {
    console.warn("ipapi.co failed", error);
  }

  return fallback;
}

function getSymbolFromCode(code: string): string {
  const symbols: Record<string, string> = {
    USD: '$', EUR: '€', GBP: '£', JPY: '¥', INR: '₹', CAD: '$', AUD: '$',
    CNY: '¥', RUB: '₽', KRW: '₩', BRL: 'R$', TRY: '₺'
  };
  return symbols[code] || '$';
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { detectUserLocation, UserLocationData } from '../services/location';

interface ConvertedPrice {
  price: number;
  formatted: string;
  currency: string;
  symbol: string;
}

interface LocationContextType {
  location: UserLocationData;
  isLoading: boolean;
  refreshLocation: () => Promise<void>;
  convertPrice: (priceInUsd: number) => ConvertedPrice;
}

const LocationContext = createContext<LocationContextType | undefined>(undefined);

// Mock exchange rates relative to USD
const RATES: Record<string, number> = {
  USD: 1,
  EUR: 0.92,
  GBP: 0.79,
  CAD: 1.36,
  AUD: 1.52,
  JPY: 150.5,
  INR: 83.2,
  CNY: 7.2,
  RUB: 92.5,
  KRW: 1330,
  BRL: 4.95,
  TRY: 31.5
};

export const LocationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [location, setLocation] = useState<UserLocationData>({
    city: 'New York',
    country: 'USA',
    currency: 'USD',
    symbol: '$',
    formattedAddress: 'New York, NY'
  });
  const [isLoading, setIsLoading] = useState(true);

  const refreshLocation = async () => {
    setIsLoading(true);
    const data = await detectUserLocation();
    setLocation(data);
    setIsLoading(false);
  };

  useEffect(() => {
    refreshLocation();
  }, []);

  const convertPrice = (priceInUsd: number): ConvertedPrice => {
    const rate = RATES[location.currency] || 1;
    // If currency not in list, fallback to USD logic (rate = 1) but use location symbol if available? 
    // Actually if rate is 1 and currency isn't USD, we might be showing wrong value.
    // For mock, we'll assume 1:1 if rate is missing to avoid huge errors, or just keep USD.

    const finalRate = RATES[location.currency] ? RATES[location.currency] : 1;
    const finalCurrency = RATES[location.currency] ? location.currency : 'USD';
    const finalSymbol = RATES[location.currency] ? location.symbol : '$';

    const converted = Math.round(priceInUsd * finalRate);

    return {
      price: converted,
      formatted: converted.toLocaleString(),
      currency: finalCurrency,
      symbol: finalSymbol
    };
  };

  return (
    <LocationContext.Provider value={{ location, isLoading, refreshLocation, convertPrice }}>
      {children}
    </LocationContext.Provider>
  );
};

export const useLocation = () => {
  const context = useContext(LocationContext);
  if (context === undefined) {
    throw new Error('useLocation must be used within a LocationProvider');
  }
  return context;
};

