export const getListingById = (id: string): Listing | undefined => {
  const paidPosts = getAllFeatured([]);
  const paidItem = paidPosts.find(p => p.id === id);
  if (paidItem) return paidItem;

  const parts = id.split('-');
  if (parts.length < 2) return undefined;

  const index = parseInt(parts[parts.length - 1]);
  const categoryId = parts.slice(0, parts.length - 1).join('-');

  if (isNaN(index)) return undefined;

  const listings = generateListings(categoryId, index + 1, 0);
  return listings[index];
};

export const getUserListings = (userId: string): Listing[] => {
   // Generate some random listings for the user profile
   const allCategories = ['electronics', 'vehicles', 'real-estate', 'fashion'];
   const listings: Listing[] = [];

   // Add some featured ones if they match
   getAllFeatured([]).forEach(l => {
     if (l.sellerId === userId) listings.push(l);
   });

   // Generate a few random ones
   for(let i=0; i<3; i++) {
      const cat = allCategories[i % allCategories.length];
      const items = generateListings(cat, 1, i+20);
      items[0].sellerId = userId;
      listings.push(items[0]);
   }
   return listings;
};

// --- CHAT SERVICES ---

export const getChatsForUser = (userId: string): Chat[] => {
  return CHATS.filter(c => c.participants.includes(userId));
};

export const getChat = (chatId: string): Chat | undefined => {
  return CHATS.find(c => c.id === chatId);
};

export const createChat = (myId: string, otherUserId: string, listingId?: string): string => {
  // Check if chat already exists
  const existing = CHATS.find(c => c.participants.includes(myId) && c.participants.includes(otherUserId));
  if (existing) return existing.id;

  const newChat: Chat = {
    id: `chat-${Date.now()}`,
    participants: [myId, otherUserId],
    listingId,
    messages: [],
    lastMessage: 'Started a new conversation',
    lastMessageTime: 'Just now',
    unreadCount: 0
  };

  CHATS = [newChat, ...CHATS];
  return newChat.id;
};

export const sendMessage = (chatId: string, senderId: string, text: string) => {
  const chatIndex = CHATS.findIndex(c => c.id === chatId);
  if (chatIndex > -1) {
    const newMessage: ChatMessage = {
      id: `msg-${Date.now()}`,
      senderId,
      text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isRead: false
    };

    // Update Chat
    const chat = { ...CHATS[chatIndex] };
    chat.messages = [...chat.messages, newMessage];
    chat.lastMessage = text;
    chat.lastMessageTime = 'Just now';

    // Move to top
    CHATS.splice(chatIndex, 1);
    CHATS = [chat, ...CHATS];
    return chat;
  }
};

