import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Listing } from '../types';
import { getUser } from '../services/mockData';
import { CATEGORIES } from '../constants';
import Icon from './Icon';
import { useLocation } from '../context/LocationContext';

interface ListingCardProps {
  listing: Listing;
}

const ListingCard: React.FC<ListingCardProps> = ({ listing }) => {
  const navigate = useNavigate();
  const seller = getUser(listing.sellerId);
  const category = CATEGORIES.find(c => c.id === listing.categoryId);
  const { convertPrice } = useLocation();
  const converted = convertPrice(listing.price);

  // Carousel Logic
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const images = listing.images && listing.images.length > 0 ? listing.images : [listing.imageUrl];

  // Touch state for swipe
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);
  const minSwipeDistance = 50;

  const nextImage = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };

  const onTouchEnd = (e: React.TouchEvent) => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe || isRightSwipe) {
       // Prevent navigation when swiping
       e.preventDefault();
       e.stopPropagation();

       if (isLeftSwipe) {
          setCurrentImageIndex((prev) => (prev + 1) % images.length);
       } else {
          setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
       }
    }
  };

  const handleChat = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if(seller) {
        navigate(`/chat?to=${seller.id}`);
    } else {
        navigate('/signin');
    }
  };

  return (
    <div className="group block h-full select-none relative">
      <div className="relative h-full bg-white rounded-3xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 hover:-translate-y-1 flex flex-col isolate ring-1 ring-slate-100">

        {/* Main Card Link - Absolute Overlay */}
        <Link to={`/listing/${listing.id}`} className="absolute inset-0 z-0" aria-label={`View ${listing.title}`} />

        {/* Image Section */}
        <div 
          className="relative aspect-[4/3] overflow-hidden bg-slate-100 group/image z-10 pointer-events-auto"
          onTouchStart={onTouchStart}
          onTouchMove={onTouchMove}
          onTouchEnd={onTouchEnd}
        >
           {/* Image Carousel */}
           {images.map((img, index) => (
              <img 
                key={index}
                src={img} 
                alt={`${listing.title} - ${index + 1}`}
                className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-300 ${index === currentImageIndex ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
                loading="lazy"
              />
           ))}

          {/* Gradient Overlay */}
          <div className="absolute inset-0 bg-gradient-to-t from-slate-900/50 via-transparent to-transparent opacity-60 group-hover:opacity-80 transition-opacity duration-500 pointer-events-none"></div>

          {/* Navigation Arrows (Desktop) */}
          {images.length > 1 && (
            <>
              <button 
                onClick={prevImage}
                className="absolute left-2 top-1/2 -translate-y-1/2 w-7 h-7 bg-white/30 backdrop-blur-md hover:bg-white/90 rounded-full flex items-center justify-center text-white hover:text-slate-800 opacity-0 group-hover/image:opacity-100 transition-all duration-200 z-20"
              >
                <Icon name="chevronRight" size={14} className="rotate-180" />
              </button>
              <button 
                onClick={nextImage}
                className="absolute right-2 top-1/2 -translate-y-1/2 w-7 h-7 bg-white/30 backdrop-blur-md hover:bg-white/90 rounded-full flex items-center justify-center text-white hover:text-slate-800 opacity-0 group-hover/image:opacity-100 transition-all duration-200 z-20"
              >
                <Icon name="chevronRight" size={14} />
              </button>
            </>
          )}

          {/* Pagination Dots */}
          {images.length > 1 && (
            <div className="absolute bottom-10 left-0 right-0 flex justify-center gap-1.5 z-20 pointer-events-none">
              {images.map((_, idx) => (
                <div 
                  key={idx} 
                  className={`w-1.5 h-1.5 rounded-full transition-all shadow-sm ${idx === currentImageIndex ? 'bg-white scale-125' : 'bg-white/40'}`}
                />
              ))}
            </div>
          )}

          {/* Floating Badges (Top Left) */}
          <div className="absolute top-3 left-3 flex flex-col gap-2 z-10 pointer-events-none">
             {listing.isFeatured && (
               <span className="px-2.5 py-1 rounded-lg bg-white/95 backdrop-blur-md text-[10px] font-bold uppercase tracking-wider text-amber-600 shadow-sm flex items-center gap-1.5 border border-amber-100">
                 <Icon name="star" size={10} className="fill-amber-500 text-amber-500" /> Featured
               </span>
             )}
          </div>

          {/* Like Button (Top Right) */}
          <button 
            onClick={(e) => { e.preventDefault(); e.stopPropagation(); }}
            className="absolute top-3 right-3 w-8 h-8 flex items-center justify-center rounded-full bg-white/80 backdrop-blur-md hover:bg-white text-slate-500 hover:text-rose-500 transition-all duration-300 shadow-sm z-20 hover:scale-110 active:scale-95 group/btn"
          >
             <Icon name="heart" size={16} className="transition-transform group-active/btn:scale-90" />
          </button>

          {/* Category Tag (Bottom Left) - Repositioned from Content to Image */}
          {category && (
            <div className={`absolute bottom-3 left-3 px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider shadow-sm z-10 ${category.color}`}>
               {category.name}
            </div>
          )}
        </div>

        {/* Content Section */}
        <div className="p-3 flex flex-col flex-grow relative bg-white z-10 pointer-events-none">

           {/* Top Row: Location & Date (Moved Location here) */}
           <div className="flex justify-between items-center mb-2">
              <div className="flex items-center gap-1 text-[10px] font-medium text-slate-500">
                 <Icon name="mapPin" size={10} className="text-slate-400" />
                 <span className="truncate max-w-[120px]">{listing.location}</span>
              </div>
              <span className="text-[10px] font-medium text-slate-400">{listing.datePosted}</span>
           </div>

           {/* Title */}
           <h3 className="text-sm font-bold text-slate-800 leading-tight mb-2 line-clamp-2 group-hover:text-brand-600 transition-colors font-display">
              {listing.title}
           </h3>

           {/* Footer: Price & Actions */}
           <div className="mt-auto pt-3 flex items-center justify-between border-t border-slate-100 pointer-events-auto">

              {/* Price - Standout (Label Removed) */}
              <div className="flex flex-col">
                  <div className="flex items-baseline gap-0.5 text-brand-600">
                    <span className="text-xs font-bold">{converted.symbol}</span>
                    <span className="text-lg font-black tracking-tight">{converted.formatted}</span>
                  </div>
              </div>

              {/* Interactive Area */}
              <div className="flex items-center gap-3">
                  {/* Seller Avatar */}
                  <div className="relative group/avatar cursor-pointer z-30">
                    <div className="w-8 h-8 rounded-full border-2 border-white shadow-md overflow-hidden relative z-10 bg-slate-100 ring-1 ring-slate-100">
                       <img 
                          src={seller?.avatar || 'https://via.placeholder.com/40'} 
                          alt="Seller" 
                          className="w-full h-full object-cover" 
                       />
                    </div>
                    {seller?.verified && (
                       <div className="absolute -bottom-1 -right-1 z-20 bg-brand-500 text-white p-[2px] rounded-full border-[1.5px] border-white">
                          <Icon name="check" size={6} />
                       </div>
                    )}

                    {/* Contact Pop-up Menu */}
                    <div className="absolute bottom-full right-0 mb-3 hidden group-hover/avatar:flex items-center gap-2 bg-white p-1.5 rounded-xl shadow-xl border border-slate-100 animate-slide-up origin-bottom-right whitespace-nowrap z-50">
                        {/* Chat */}
                        <button 
                            onClick={handleChat}
                            className="w-8 h-8 flex items-center justify-center rounded-lg bg-brand-50 text-brand-600 hover:bg-brand-500 hover:text-white transition-colors border border-brand-100"
                            title="Chat"
                        >
                            <Icon name="messageCircle" size={16} />
                        </button>

                        {/* Phone */}
                        {seller?.socials.phone && (
                            <a 
                                href={`tel:${seller.socials.phone}`}
                                onClick={(e) => e.stopPropagation()}
                                className="w-8 h-8 flex items-center justify-center rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-500 hover:text-white transition-colors border border-emerald-100"
                                title="Call"
                            >
                                <Icon name="phone" size={16} />
                            </a>
                        )}

                        {/* WhatsApp */}
                        {seller?.socials.whatsapp && (
                            <a 
                                href={`https://wa.me/${seller.socials.whatsapp}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="w-8 h-8 flex items-center justify-center rounded-lg bg-[#f0fdf4] text-[#25D366] hover:bg-[#25D366] hover:text-white transition-colors border border-green-100"
                                title="WhatsApp"
                            >
                                <Icon name="whatsapp" size={16} />
                            </a>
                        )}

                        {/* Instagram */}
                        {seller?.socials.instagram && (
                            <a 
                                href={`https://instagram.com/${seller.socials.instagram}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="w-8 h-8 flex items-center justify-center rounded-lg bg-pink-50 text-pink-600 hover:bg-pink-500 hover:text-white transition-colors border border-pink-100"
                                title="Instagram"
                            >
                                <Icon name="instagram" size={16} />
                            </a>
                        )}

                        {/* Arrow nub for visual connection */}
                        <div className="absolute -bottom-1.5 right-3 w-3 h-3 bg-white border-b border-r border-slate-100 rotate-45"></div>
                    </div>
                  </div>
              </div>
           </div>
        </div>

      </div>
    </div>
  );
};

export default ListingCard;

