export const createDeliveryRequest = (listing: Listing, buyerId: string): DeliveryRequest => {
    const request: DeliveryRequest = {
        id: `del-${Date.now()}`,
        listingId: listing.id,
        buyerId: buyerId,
        sellerId: listing.sellerId,
        status: 'PENDING',
        fee: 0,
        pickupAddress: listing.location, // Simplified for mock
        dropoffAddress: 'Your Current Location', // Simplified
        timestamp: 'Just now',
        listingImage: listing.imageUrl,
        listingTitle: listing.title
    };
    DELIVERY_REQUESTS = [request, ...DELIVERY_REQUESTS];
    return request;
};

export const getDeliveryRequestsForRider = (riderId: string): DeliveryRequest[] => {
    // Return requests that are either unassigned (PENDING) OR assigned to this rider
    return DELIVERY_REQUESTS.filter(r => 
        (r.status === 'PENDING') || (r.riderId === riderId)
    );
};

export const assignRiderToRequest = (requestId: string, riderId: string) => {
    const req = DELIVERY_REQUESTS.find(r => r.id === requestId);
    if (req) {
        req.riderId = riderId;
        req.status = 'NEGOTIATING';
        // Auto-create chat between rider and buyer
        createChat(riderId, req.buyerId, req.listingId);
    }
};

export const updateDeliveryStatus = (requestId: string, status: DeliveryStatus, fee?: number) => {
    const req = DELIVERY_REQUESTS.find(r => r.id === requestId);
    if (req) {
        req.status = status;
        if (fee !== undefined) req.fee = fee;
    }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User } from '../types';
import { getUser } from '../services/mockData';

interface AuthContextType {
  user: User | null;
  login: () => void;
  loginAsRider: () => void;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  // Check local storage on mount to persist session
  useEffect(() => {
    const storedUserId = localStorage.getItem('tym2muv_user_id');
    if (storedUserId) {
      const foundUser = getUser(storedUserId);
      if (foundUser) setUser(foundUser);
    }
  }, []);

  const login = () => {
    // Simulating login as the mock "user-me"
    const mockUser = getUser('user-me');
    if (mockUser) {
      setUser(mockUser);
      localStorage.setItem('tym2muv_user_id', 'user-me');
    }
  };

  const loginAsRider = () => {
    // Simulating login as the mock rider
    const mockRider = getUser('user-rider');
    if (mockRider) {
      setUser(mockRider);
      localStorage.setItem('tym2muv_user_id', 'user-rider');
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('tym2muv_user_id');
  };

  return (
    <AuthContext.Provider value={{ user, login, loginAsRider, logout, isAuthenticated: !!user }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

