const RiderDashboard: React.FC = () => {
  const { user } = useAuth();
  const [requests, setRequests] = useState<DeliveryRequest[]>([]);
  const [activeRequest, setActiveRequest] = useState<DeliveryRequest | undefined>(undefined);
  const [isOnline, setIsOnline] = useState(user?.riderStatus === 'online' || true);
  const [feeInput, setFeeInput] = useState<string>('');

  useEffect(() => {
    if (user?.isRider) {
      refreshRequests();
      const interval = setInterval(refreshRequests, 5000); // Poll for new requests
      return () => clearInterval(interval);
    }
  }, [user]);

  const refreshRequests = () => {
    if (!user) return;
    const reqs = getDeliveryRequestsForRider(user.id);
    setRequests(reqs);

    // Find active job (not pending or cancelled or delivered)
    const active = reqs.find(r => r.status !== 'PENDING' && r.status !== 'DELIVERED' && r.status !== 'CANCELLED');
    setActiveRequest(active);
    if (active && active.fee) setFeeInput(active.fee.toString());
  };

  const handleAccept = (req: DeliveryRequest) => {
    if (user) {
      assignRiderToRequest(req.id, user.id);
      refreshRequests();
    }
  };

  const handleUpdateFee = () => {
    if (activeRequest && feeInput) {
        updateDeliveryStatus(activeRequest.id, 'ACCEPTED', parseFloat(feeInput));
        refreshRequests();
    }
