import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getListingById, getUser, createChat, createDeliveryRequest } from '../services/mockData';
import { Listing, User } from '../types';
import Icon from '../components/Icon';
import { draftBuyerMessage } from '../services/ai';
import { useLocation } from '../context/LocationContext';
import { useAuth } from '../context/AuthContext';

const ListingDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [listing, setListing] = useState<Listing | undefined>(undefined);
  const [seller, setSeller] = useState<User | undefined>(undefined);
  const [message, setMessage] = useState('');
  const [isAiDrafting, setIsAiDrafting] = useState(false);
  const [deliveryRequested, setDeliveryRequested] = useState(false);
  const { convertPrice } = useLocation();

  useEffect(() => {
    if (id) {
      const data = getListingById(id);
      setListing(data);
      if (data && data.sellerId) {
         setSeller(getUser(data.sellerId));
      }
    }
  }, [id]);

  const handleAiDraft = async (intent: string) => {
    if (!listing) return;
    setIsAiDrafting(true);
    const draft = await draftBuyerMessage(intent, listing.title);
    setMessage(draft);
    setIsAiDrafting(false);
  };

  const handleStartChat = () => {
    if (listing && seller) {
      // Create chat with 'user-me' (current user) and seller
      const chatId = createChat('user-me', seller.id, listing.id);
      navigate(`/chat?id=${chatId}`);
    }
  };

  const handleRequestDelivery = () => {
      if (!user) {
          navigate('/signin', { state: { from: { pathname: `/listing/${id}` } } });
          return;
      }
      if (listing) {
          setDeliveryRequested(true);
          createDeliveryRequest(listing, user.id);
          // Auto-start chat with seller to notify them
          createChat(user.id, listing.sellerId, listing.id);

          setTimeout(() => setDeliveryRequested(false), 3000); // Reset after 3s
      }
  };

  const handleWhatsApp = () => {
    if (seller?.socials.whatsapp) {
      window.open(`https://wa.me/${seller.socials.whatsapp}`, '_blank');
    } else {
      alert("This seller hasn't provided a WhatsApp number.");
    }
  };

  if (!listing) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh]">
        <div className="animate-spin text-brand-500 mb-4"><Icon name="loader" size={32} /></div>
        <p className="text-slate-500">Loading details...</p>
      </div>
    );
  }

  const convertedPrice = convertPrice(listing.price);

  return (
    <div className="container mx-auto px-4 py-8 animate-fade-in">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-slate-500 mb-6">
        <Link to="/" className="hover:text-brand-600">Home</Link>
        <Icon name="chevronRight" size={12} />
        <Link to={`/category/${listing.categoryId}`} className="hover:text-brand-600 capitalize">{listing.categoryId.replace('-', ' ')}</Link>
        <Icon name="chevronRight" size={12} />
        <span className="text-slate-900 truncate max-w-[200px]">{listing.title}</span>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Images & Info */}
        <div className="lg:col-span-2 space-y-8">
          {/* Image Gallery */}
          <div className="bg-slate-100 rounded-3xl overflow-hidden aspect-video relative group">
            <img src={listing.imageUrl} alt={listing.title} className="w-full h-full object-cover" />
            <div className="absolute top-4 right-4">
               <button className="bg-white/90 backdrop-blur p-2.5 rounded-full text-slate-400 hover:text-red-500 transition-colors shadow-lg">
                 <Icon name="heart" size={24} />
               </button>
            </div>
            {listing.isFeatured && (
               <div className="absolute top-4 left-4 bg-yellow-400 text-yellow-900 text-xs font-bold px-3 py-1.5 rounded-lg shadow-lg uppercase tracking-wider">
                 Featured Pick
               </div>
            )}
          </div>

          {/* Details */}
          <div className="bg-white rounded-3xl p-8 border border-slate-100 shadow-sm">
             <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 border-b border-slate-100 pb-6">
                <div>
                   <h1 className="text-2xl md:text-3xl font-bold text-slate-900 mb-2">{listing.title}</h1>
                   <div className="flex items-center gap-4 text-sm text-slate-500">
                      <span className="flex items-center gap-1"><Icon name="mapPin" size={16} /> {listing.location}</span>
                      <span className="flex items-center gap-1"><Icon name="activity" size={16} /> Posted {listing.datePosted}</span>
                   </div>
                </div>
                <div className="text-3xl font-bold text-brand-600">
                   {convertedPrice.symbol}{convertedPrice.formatted}
                </div>
             </div>

             <div className="space-y-4">
                <h3 className="font-bold text-lg text-slate-900">Description</h3>
                <p className="text-slate-600 leading-relaxed">
                   This is a placeholder description for the item. In a real application, this would be fetched from the backend. 
                   The item is located in {listing.location} and is available for immediate purchase.
                   Excellent condition, barely used. Comes with original packaging and all accessories.
                </p>
                <div className="flex gap-2 flex-wrap mt-4">
                   {['Verified Seller', 'Fast Response', 'Negotiable'].map(tag => (
                      <span key={tag} className="px-3 py-1 bg-slate-100 text-slate-600 rounded-full text-xs font-medium">
                         {tag}
                      </span>
                   ))}
                </div>
             </div>
          </div>
        </div>

        {/* Right Column: Contact & Action */}
        <div className="lg:col-span-1">
           <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-xl shadow-slate-200/50 sticky top-24">
              {seller ? (
                <div className="flex items-center gap-4 mb-6 pb-6 border-b border-slate-100">
                  <Link to={`/profile/${seller.id}`} className="block relative group flex-shrink-0">
                    <img src={seller.avatar} alt={seller.name} className="w-16 h-16 rounded-full object-cover border-2 border-brand-100 group-hover:border-brand-500 transition-colors shadow-sm" />
                    {seller.verified && (
                       <div className="absolute -bottom-1 -right-1 bg-brand-500 text-white p-1 rounded-full border-2 border-white">
                          <Icon name="check" size={10} />
                       </div>
                    )}
                  </Link>
                  <div className="min-w-0">
                    <Link to={`/profile/${seller.id}`} className="font-bold text-slate-900 hover:text-brand-600 text-lg flex items-center gap-2 truncate">
                        {seller.name}
                        {seller.verified && (
                            <span className="flex-shrink-0 bg-brand-100 text-brand-600 text-[10px] px-2 py-0.5 rounded-full border border-brand-200 flex items-center gap-1 uppercase tracking-wider font-bold">
                                <Icon name="check" size={10} /> Verified
                            </span>
                        )}
                    </Link>

                    {/* Seller Location */}
                    <div className="flex items-center gap-1.5 text-xs text-slate-500 mb-1">
                        <Icon name="mapPin" size={12} className="text-slate-400" />
                        <span className="truncate">{seller.location}</span>
                    </div>

                    <div className="flex items-center gap-1 text-xs text-brand-600 mb-2">
                        <Icon name="star" size={12} className="fill-brand-600" /> 
                        <span className="font-semibold">{seller.rating}</span>
                        <span className="text-slate-400 font-normal">({seller.reviewCount} reviews)</span>
                    </div>

                    <p className="text-xs text-slate-500 line-clamp-1 mb-3">{seller.bio}</p>

                    {/* Contact Icons */}
                    <div className="flex gap-2 flex-wrap">
                       {seller.socials.phone && (
                          <a href={`tel:${seller.socials.phone}`} className="w-8 h-8 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-emerald-100" title="Call">
                             <Icon name="phone" size={14} />
                          </a>
                       )}
                       {seller.socials.email && (
                          <a href={`mailto:${seller.socials.email}`} className="w-8 h-8 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center hover:bg-blue-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-blue-100" title="Email">
                             <Icon name="mail" size={14} />
                          </a>
                       )}
                       {seller.socials.website && (
                          <a href={seller.socials.website.startsWith('http') ? seller.socials.website : `https://${seller.socials.website}`} target="_blank" rel="noopener noreferrer" className="w-8 h-8 rounded-full bg-purple-50 text-purple-600 flex items-center justify-center hover:bg-purple-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-purple-100" title="Website">
                             <Icon name="globe" size={14} />
                          </a>
                       )}

                       {/* Socials Separator if both exist */}
                       {(seller.socials.phone || seller.socials.email || seller.socials.website) && (seller.socials.facebook || seller.socials.instagram || seller.socials.twitter || seller.socials.linkedin) && (
                           <div className="w-px bg-slate-200 mx-1 h-6 self-center"></div>
                       )}

                       {seller.socials.facebook && <a href={`https://facebook.com/${seller.socials.facebook}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-[#1877F2] hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="facebook" size={14} /></a>}
                       {seller.socials.instagram && <a href={`https://instagram.com/${seller.socials.instagram}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-pink-600 hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="instagram" size={14} /></a>}
                       {seller.socials.twitter && <a href={`https://twitter.com/${seller.socials.twitter}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-sky-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="twitter" size={14} /></a>}
                       {seller.socials.linkedin && <a href={`https://linkedin.com/in/${seller.socials.linkedin}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-blue-700 hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="linkedin" size={14} /></a>}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="mb-6 pb-6 border-b border-slate-100">
                  <div className="animate-pulse flex items-center gap-4">
                     <div className="w-16 h-16 bg-slate-200 rounded-full"></div>
                     <div className="flex-1 space-y-2">
                        <div className="h-4 bg-slate-200 rounded w-3/4"></div>
                        <div className="h-3 bg-slate-200 rounded w-1/2"></div>
                     </div>
                  </div>
                </div>
              )}

              <div className="space-y-4">
                 {/* BUY WITH DELIVERY BUTTON */}
                 <button 
                    onClick={handleRequestDelivery}
                    disabled={deliveryRequested}
