                 >
                    {deliveryRequested ? (
                        <>
                            <Icon name="check" size={20} /> Request Sent!
                        </>
                    ) : (
                        <>
                            <Icon name="truck" size={20} /> Buy with Delivery
                        </>
                    )}
                 </button>

                 {/* WhatsApp Button */}
                 <button 
                    onClick={handleWhatsApp}
                    className="w-full bg-[#25D366] text-white py-3.5 rounded-xl font-bold hover:bg-[#128C7E] transition-colors shadow-lg shadow-green-500/20 flex items-center justify-center gap-2"
                 >
                    <Icon name="whatsapp" size={20} />
