                    <span className="truncate max-w-[100px]">{userLocData.formattedAddress || "Location"}</span>
                    </button>

                    {/* Rider Dashboard Link (If Rider) */}
                    {isAuthenticated && user?.isRider && (
                        <Link 
                        to="/rider-dashboard" 
                        className="flex items-center gap-2 bg-slate-800 hover:bg-slate-900 text-white px-3 py-2.5 rounded-xl font-bold transition-all"
                        >
                        <Icon name="truck" size={18} />
                        <span className="hidden sm:inline">Rider Panel</span>
                        </Link>
                    )}

                    {/* Post Button (Hidden if rider for clean UX, or keep it) */}
                    {!user?.isRider && (
                        <Link 
                        to="/post" 
                        className="flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white px-5 py-2.5 rounded-xl font-bold transition-all shadow-lg shadow-brand-500/30 active:scale-95"
                        >
                        <Icon name="plus" size={18} strokeWidth={3} />
                        <span>Post</span>
                        </Link>
                    )}

                    {/* Auth */}
                    {isAuthenticated ? (
                    <div className="flex items-center gap-2">
                        <Link to="/chat" className="p-2 text-slate-500 hover:text-brand-600 hover:bg-brand-50 rounded-full transition-all relative group">
