                    />
                </div>

                {/* Actions */}
                <div className="flex items-center gap-3 sm:gap-4 flex-shrink-0">

                    {/* Location (Hidden on mobile) */}
                    <button 
                    onClick={handleManualLocate}
                    className="hidden xl:flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-medium text-slate-500 hover:bg-brand-50 hover:text-brand-600 transition-all"
                    title="Update Location"
                    >
                    <Icon name="mapPin" size={14} className={`text-brand-500 ${isLocating ? 'animate-bounce' : ''}`} />
                    <span className="truncate max-w-[100px]">{userLocData.formattedAddress || "Location"}</span>
                    </button>

                    {/* Rider Dashboard Link (If Rider) */}
                    {isAuthenticated && user?.isRider && (
                        <Link 
                        to="/rider-dashboard" 
                        className="flex items-center gap-2 bg-slate-800 hover:bg-slate-900 text-white px-3 py-2.5 rounded-xl font-bold transition-all"
                        >
                        <Icon name="truck" size={18} />
                        <span className="hidden sm:inline">Rider Panel</span>
                        </Link>
                    )}

                    {/* Post Button (Hidden if rider for clean UX, or keep it) */}
                    {!user?.isRider && (
                        <Link 
                        to="/post" 
                        className="flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white px-5 py-2.5 rounded-xl font-bold transition-all shadow-lg shadow-brand-500/30 active:scale-95"
                        >
                        <Icon name="plus" size={18} strokeWidth={3} />
                        <span>Post</span>
                        </Link>
                    )}

                    {/* Auth */}
                    {isAuthenticated ? (
                    <div className="flex items-center gap-2">
                        <Link to="/chat" className="p-2 text-slate-500 hover:text-brand-600 hover:bg-brand-50 rounded-full transition-all relative group">
                        <Icon name="messageCircle" size={22} />
                        <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 border border-white rounded-full"></span>
                        </Link>
                        <Link to="/profile/me" className="w-10 h-10 rounded-full bg-slate-100 p-0.5 border border-slate-200 cursor-pointer hover:ring-2 hover:ring-brand-200 transition-all">
