                    <Icon name="chevronRight" size={20} className="rotate-180" />
                </button>
                <button 
                    onClick={() => scroll('right')}
                    className="absolute right-2 top-1/2 -translate-y-1/2 z-20 w-8 h-8 rounded-full bg-white shadow-md border border-slate-100 flex items-center justify-center text-slate-600 hover:text-brand-600 hover:scale-110 transition-all opacity-0 group-hover/cat-nav:opacity-100 focus:opacity-100 active:scale-95 md:opacity-100"
                    aria-label="Scroll right"
                >
                    <Icon name="chevronRight" size={20} />
                </button>

                <div className="overflow-hidden py-3">
                    <div 
                        ref={scrollContainerRef}
                        className="flex items-start gap-4 overflow-x-auto scroll-smooth no-scrollbar px-4"
                        style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
