import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Listing } from '../types';
import { getUser } from '../services/mockData';
import { CATEGORIES } from '../constants';
import Icon from './Icon';
import { useLocation } from '../context/LocationContext';

interface ListingCardProps {
  listing: Listing;
}

const ListingCard: React.FC<ListingCardProps> = ({ listing }) => {
  const navigate = useNavigate();
  const seller = getUser(listing.sellerId);
  const category = CATEGORIES.find(c => c.id === listing.categoryId);
  const { convertPrice } = useLocation();
  const converted = convertPrice(listing.price);

  // Carousel Logic
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const images = listing.images && listing.images.length > 0 ? listing.images : [listing.imageUrl];

  // Auto-slide Logic
  useEffect(() => {
    if (images.length <= 1) return;

    const interval = setInterval(() => {
      setCurrentImageIndex((prev) => (prev + 1) % images.length);
    }, 8000); // Change every 8 seconds

    return () => clearInterval(interval);
  }, [currentImageIndex, images.length]); // Reset timer when image changes (manually or automatically)

  // Touch state for swipe
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);
  const minSwipeDistance = 50;

  const nextImage = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };

  const onTouchEnd = (e: React.TouchEvent) => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe || isRightSwipe) {
       // Prevent navigation when swiping
       e.preventDefault();
       e.stopPropagation();

       if (isLeftSwipe) {
          setCurrentImageIndex((prev) => (prev + 1) % images.length);
       } else {
          setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
       }
    }
  };

  const handleChat = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if(seller) {
        navigate(`/chat?to=${seller.id}`);
    } else {
        navigate('/signin');
    }
  };

  return (
    <div className="group block h-full select-none relative">
      <div className="relative h-full bg-white rounded-3xl shadow-sm transition-all duration-500 hover:-translate-y-2 hover:shadow-[0_20px_40px_-15px_rgba(147,51,234,0.15)] flex flex-col isolate ring-1 ring-slate-100 hover:ring-brand-200">

        {/* Main Card Link - Absolute Overlay */}
        <Link to={`/listing/${listing.id}`} className="absolute inset-0 z-0 rounded-3xl" aria-label={`View ${listing.title}`} />

        {/* Image Section - Rounded top corners only */}
        <div 
          className="relative aspect-[4/3] overflow-hidden bg-slate-100 rounded-t-3xl group/image z-10 pointer-events-auto"
          onTouchStart={onTouchStart}
          onTouchMove={onTouchMove}
          onTouchEnd={onTouchEnd}
        >
           {/* Image Carousel */}
           {images.map((img, index) => (
              <img 
                key={index}
                src={img} 
                alt={`${listing.title} - ${index + 1}`}
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-700 ease-in-out group-hover:scale-110 ${index === currentImageIndex ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
                loading="lazy"
              />
           ))}

          {/* Gradient Overlay */}
          <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none"></div>

          {/* Navigation Arrows (Desktop) */}
          {images.length > 1 && (
            <>
              <button 
                onClick={prevImage}
                className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-white/20 backdrop-blur-md hover:bg-white/90 rounded-full flex items-center justify-center text-white hover:text-slate-800 opacity-0 group-hover/image:opacity-100 transition-all duration-300 z-20 translate-x-2 group-hover/image:translate-x-0"
              >
                <Icon name="chevronRight" size={16} className="rotate-180" />
              </button>
              <button 
                onClick={nextImage}
                className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-white/20 backdrop-blur-md hover:bg-white/90 rounded-full flex items-center justify-center text-white hover:text-slate-800 opacity-0 group-hover/image:opacity-100 transition-all duration-300 z-20 -translate-x-2 group-hover/image:translate-x-0"
              >
                <Icon name="chevronRight" size={16} />
              </button>
            </>
          )}

          {/* Pagination Dots */}
          {images.length > 1 && (
            <div className="absolute bottom-3 left-0 right-0 flex justify-center gap-1.5 z-20 pointer-events-none">
              {images.map((_, idx) => (
                <div 
                  key={idx} 
                  className={`w-1.5 h-1.5 rounded-full transition-all shadow-sm ${idx === currentImageIndex ? 'bg-white scale-125' : 'bg-white/40'}`}
                />
              ))}
            </div>
          )}

          {/* Floating Badges (Top Left) */}
          <div className="absolute top-3 left-3 flex flex-col gap-2 z-10 pointer-events-none">
             {listing.isFeatured && (
               <span className="px-2.5 py-1 rounded-lg bg-white/95 backdrop-blur-md text-[10px] font-bold uppercase tracking-wider text-amber-600 shadow-sm flex items-center gap-1.5 border border-amber-100">
                 <Icon name="star" size={10} className="fill-amber-500 text-amber-500" /> Featured
               </span>
             )}
          </div>

          {/* Like Button (Top Right) */}
          <button 
            onClick={(e) => { e.preventDefault(); e.stopPropagation(); }}
            className="absolute top-3 right-3 w-9 h-9 flex items-center justify-center rounded-full bg-white/80 backdrop-blur-md hover:bg-white text-slate-500 hover:text-rose-500 transition-all duration-300 shadow-sm z-20 hover:scale-110 active:scale-95 group/btn"
          >
             <Icon name="heart" size={18} className="transition-transform group-active/btn:scale-90" />
          </button>

        </div>

        {/* Content Section - Rounded bottom corners only */}
        <div className="p-4 flex flex-col flex-grow relative bg-white rounded-b-3xl z-10 pointer-events-none">

           {/* Top Row: Location & Date (Moved Location here) */}
           <div className="flex justify-between items-center mb-2">
              <div className="flex items-center gap-1 text-[11px] font-medium text-slate-500">
                 <Icon name="mapPin" size={12} className="text-slate-400" />
                 <span className="truncate max-w-[120px]">{listing.location}</span>
              </div>
              <span className="text-[10px] font-medium text-slate-400 bg-slate-50 px-2 py-0.5 rounded-full">{listing.datePosted}</span>
           </div>

           {/* Title */}
           <h3 className="text-[15px] font-wix font-bold text-slate-800 leading-snug mb-2 line-clamp-2 group-hover:text-brand-600 transition-colors">
              {listing.title}
           </h3>

           {/* Footer: Price & Actions */}
           <div className="mt-auto pt-3 flex items-center justify-between border-t border-slate-50 pointer-events-auto">

              {/* Price - Standout (Label Removed) */}
              <div className="flex flex-col">
                  <div className="flex items-baseline gap-0.5 text-brand-600 group-hover:text-brand-700 transition-colors">
                    <span className="text-xs font-bold">{converted.symbol}</span>
                    <span className="text-xl font-wix font-extrabold tracking-tight">{converted.formatted}</span>
                  </div>
              </div>

              {/* Interactive Area */}
              <div className="flex items-center gap-3">
                  {/* Seller Avatar */}
                  <div className="relative group/avatar cursor-pointer z-30">
                    <div className="w-8 h-8 rounded-full border-2 border-white shadow-md overflow-hidden relative z-10 bg-slate-100 ring-1 ring-slate-100 group-hover:ring-brand-200 transition-all">
                       <img 
                          src={seller?.avatar || 'https://via.placeholder.com/40'} 
                          alt="Seller" 
                          className="w-full h-full object-cover" 
                       />
                    </div>
                    {seller?.verified && (
                       <div className="absolute -bottom-1 -right-1 z-20 bg-brand-500 text-white p-[2px] rounded-full border-[1.5px] border-white">
                          <Icon name="check" size={6} />
                       </div>
                    )}

                    {/* Contact Pop-up Menu - REVEAL TO THE LEFT */}
                    <div className="absolute right-full top-1/2 -translate-y-1/2 mr-3 hidden group-hover/avatar:flex items-center gap-2 bg-white p-1.5 rounded-xl shadow-xl border border-slate-100 animate-fade-in origin-right whitespace-nowrap z-50">
                        {/* Chat */}
                        <button 
                            onClick={handleChat}
                            className="w-8 h-8 flex items-center justify-center rounded-lg bg-brand-50 text-brand-600 hover:bg-brand-500 hover:text-white transition-colors border border-brand-100"
                            title="Chat"
                        >
                            <Icon name="messageCircle" size={16} />
                        </button>

                        {/* Phone */}
                        {seller?.socials.phone && (
                            <a 
                                href={`tel:${seller.socials.phone}`}
                                onClick={(e) => e.stopPropagation()}
                                className="w-8 h-8 flex items-center justify-center rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-500 hover:text-white transition-colors border border-emerald-100"
                                title="Call"
                            >
                                <Icon name="phone" size={16} />
                            </a>
                        )}

                        {/* WhatsApp */}
                        {seller?.socials.whatsapp && (
                            <a 
                                href={`https://wa.me/${seller.socials.whatsapp}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="w-8 h-8 flex items-center justify-center rounded-lg bg-[#f0fdf4] text-[#25D366] hover:bg-[#25D366] hover:text-white transition-colors border border-green-100"
                                title="WhatsApp"
                            >
                                <Icon name="whatsapp" size={16} />
                            </a>
                        )}

                        {/* Arrow nub */}
                        <div className="absolute top-1/2 -right-1.5 -translate-y-1/2 w-3 h-3 bg-white border-t border-r border-slate-100 rotate-45"></div>
                    </div>
                  </div>
              </div>
           </div>
        </div>

      </div>
    </div>
  );
};

