import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { getChatsForUser, getChat, getUser, sendMessage, createChat } from '../services/mockData';
import { Chat as ChatType, User } from '../types';
import Icon from '../components/Icon';

const Chat: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [chats, setChats] = useState<ChatType[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [activeChat, setActiveChat] = useState<ChatType | undefined>(undefined);
  const [messageInput, setMessageInput] = useState('');

  // Resolve other participant details
  const [participants, setParticipants] = useState<Record<string, User>>({});

  useEffect(() => {
    // Initialize Chats
    const myChats = getChatsForUser('user-me');
    setChats(myChats);

    // Resolve Users
    const userIds = new Set<string>();
    myChats.forEach(c => c.participants.forEach(p => userIds.add(p)));

    // Also check url params for starting a new chat
    const newChatId = searchParams.get('id');
    const startWithUserId = searchParams.get('to');

    if (newChatId) {
       setActiveChatId(newChatId);
    } else if (startWithUserId) {
       const createdId = createChat('user-me', startWithUserId);
       setActiveChatId(createdId);
       // Refresh chats to include new one
       setChats(getChatsForUser('user-me'));
       userIds.add(startWithUserId);
    } else if (myChats.length > 0 && window.innerWidth > 768) {
       // Auto select first chat on desktop
       setActiveChatId(myChats[0].id);
    }

    // Fetch user details
    const userMap: Record<string, User> = {};
    userIds.forEach(uid => {
        const u = getUser(uid);
        if (u) userMap[uid] = u;
    });
    setParticipants(userMap);

  }, [searchParams]);

  useEffect(() => {
    if (activeChatId) {
        setActiveChat(getChat(activeChatId));
    }
  }, [activeChatId, chats]);

  const handleSendMessage = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!messageInput.trim() || !activeChatId) return;

    sendMessage(activeChatId, 'user-me', messageInput);

    // Refresh UI
    setChats(getChatsForUser('user-me'));
    setMessageInput('');
  };

  const getOtherParticipant = (chat: ChatType) => {
    const otherId = chat.participants.find(p => p !== 'user-me');
    return otherId ? participants[otherId] : undefined;
  };

  return (
    <div className="container mx-auto px-4 pt-12 pb-8 h-[calc(100vh-5rem)]"> {/* Standardized padding with gap */}
       <div className="bg-white rounded-3xl shadow-lg border border-slate-200 h-full overflow-hidden flex">

          {/* Sidebar / Inbox List */}
          <div className={`${activeChatId ? 'hidden md:flex' : 'flex'} w-full md:w-80 lg:w-96 flex-col border-r border-slate-200`}>
             <div className="p-6 border-b border-slate-100">
                <h2 className="text-xl font-bold text-slate-800">Messages</h2>
             </div>
             <div className="flex-1 overflow-y-auto custom-scrollbar">
                {chats.length === 0 ? (
                    <div className="p-8 text-center text-slate-500">
                        <Icon name="messageCircle" size={32} className="mx-auto mb-2 text-slate-300" />
                        <p>No messages yet.</p>
                    </div>
                ) : (
                    chats.map(chat => {
                        const otherUser = getOtherParticipant(chat);
                        return (
                            <div 
                                key={chat.id}
                                onClick={() => setActiveChatId(chat.id)}
                                className={`p-4 border-b border-slate-50 cursor-pointer hover:bg-slate-50 transition-colors ${activeChatId === chat.id ? 'bg-brand-50/50 border-l-4 border-l-brand-500' : 'border-l-4 border-l-transparent'}`}
                            >
                                <div className="flex gap-3">
                                    <img 
                                      src={otherUser?.avatar || 'https://via.placeholder.com/50'} 
                                      alt={otherUser?.name} 
                                      className="w-12 h-12 rounded-full object-cover bg-slate-200"
                                    />
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-baseline mb-1">
                                            <h3 className="font-bold text-slate-900 truncate">{otherUser?.name || 'User'}</h3>
                                            <span className="text-xs text-slate-400">{chat.lastMessageTime}</span>
                                        </div>
                                        <p className={`text-sm truncate ${chat.unreadCount > 0 ? 'font-bold text-slate-800' : 'text-slate-500'}`}>
                                            {chat.lastMessage}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}
             </div>
          </div>

          {/* Chat Window */}
          <div className={`${!activeChatId ? 'hidden md:flex' : 'flex'} flex-1 flex-col bg-slate-50/50`}>
              {activeChatId ? (
                  <>
                    {/* Header */}
                    <div className="p-4 bg-white border-b border-slate-200 flex items-center gap-3 shadow-sm">
                        <button onClick={() => setActiveChatId(null)} className="md:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-full">
                            <Icon name="chevronRight" size={20} className="rotate-180" />
                        </button>
                        {(() => {
                            const otherUser = activeChat && getOtherParticipant(activeChat);
                            return otherUser ? (
                                <div className="flex items-center gap-3">
                                    <div className="relative">
                                        <img src={otherUser.avatar} alt={otherUser.name} className="w-10 h-10 rounded-full object-cover" />
                                        {otherUser.verified && (
                                            <div className="absolute -bottom-1 -right-1 bg-brand-500 text-white p-0.5 rounded-full border border-white">
                                                <Icon name="check" size={8} />
                                            </div>
                                        )}
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-slate-900">{otherUser.name}</h3>
                                        <p className="text-xs text-brand-600 flex items-center gap-1">
                                            {activeChat?.listingId && <><Icon name="box" size={10} /> Listing Inquiry</>}
                                        </p>
                                    </div>
                                </div>
                            ) : null;
                        })()}
                    </div>

                    {/* Messages Area */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                        {activeChat?.messages.map((msg) => {
                            const isMe = msg.senderId === 'user-me';
                            return (
                                <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`max-w-[75%] px-5 py-3 rounded-2xl ${
                                        isMe 
                                        ? 'bg-brand-600 text-white rounded-tr-sm' 
                                        : 'bg-white text-slate-800 shadow-sm border border-slate-100 rounded-tl-sm'
                                    }`}>
                                        <p className="text-sm">{msg.text}</p>
                                        <p className={`text-[10px] mt-1 text-right ${isMe ? 'text-brand-200' : 'text-slate-400'}`}>{msg.timestamp}</p>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {/* Input Area */}
                    <div className="p-4 bg-white border-t border-slate-200">
                        <form onSubmit={handleSendMessage} className="flex items-center gap-2">
                            <button type="button" className="p-2 text-slate-400 hover:text-brand-600 hover:bg-slate-100 rounded-full transition-colors">
                                <Icon name="plus" size={24} />
                            </button>
                            <input 
                                type="text" 
                                value={messageInput}
                                onChange={(e) => setMessageInput(e.target.value)}
                                placeholder="Type a message..." 
                                className="flex-1 bg-slate-100 border-none rounded-xl px-4 py-3 focus:ring-2 focus:ring-brand-500 outline-none"
                            />
                            <button 
                                type="submit" 
                                disabled={!messageInput.trim()}
                                className="p-3 bg-brand-600 text-white rounded-xl hover:bg-brand-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-md shadow-brand-500/20"
                            >
                                <Icon name="send" size={20} />
                            </button>
                        </form>
                    </div>
                  </>
              ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
                      <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                          <Icon name="messageCircle" size={48} className="text-slate-300" />
                      </div>
                      <p className="text-lg">Select a conversation to start chatting</p>
                  </div>
              )}
          </div>
       </div>
    </div>
  );
};

export default Chat;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { getDeliveryRequestsForRider, assignRiderToRequest, updateDeliveryStatus } from '../services/mockData';
import { DeliveryRequest } from '../types';
import Icon from '../components/Icon';
import { Link } from 'react-router-dom';

const RiderDashboard: React.FC = () => {
  const { user } = useAuth();
  const [requests, setRequests] = useState<DeliveryRequest[]>([]);
  const [activeRequest, setActiveRequest] = useState<DeliveryRequest | undefined>(undefined);
  const [isOnline, setIsOnline] = useState(user?.riderStatus === 'online' || true);
  const [feeInput, setFeeInput] = useState<string>('');

  useEffect(() => {
    if (user?.isRider) {
      refreshRequests();
      const interval = setInterval(refreshRequests, 5000); // Poll for new requests
      return () => clearInterval(interval);
    }
  }, [user]);

  const refreshRequests = () => {
    if (!user) return;
    const reqs = getDeliveryRequestsForRider(user.id);
    setRequests(reqs);

    // Find active job (not pending or cancelled or delivered)
    const active = reqs.find(r => r.status !== 'PENDING' && r.status !== 'DELIVERED' && r.status !== 'CANCELLED');
    setActiveRequest(active);
    if (active && active.fee) setFeeInput(active.fee.toString());
  };

  const handleAccept = (req: DeliveryRequest) => {
    if (user) {
      assignRiderToRequest(req.id, user.id);
      refreshRequests();
    }
  };

  const handleUpdateFee = () => {
    if (activeRequest && feeInput) {
        updateDeliveryStatus(activeRequest.id, 'ACCEPTED', parseFloat(feeInput));
        refreshRequests();
    }
  };

  const handleStatusUpdate = (status: 'PICKED_UP' | 'DELIVERED') => {
      if (activeRequest) {
          updateDeliveryStatus(activeRequest.id, status);
          refreshRequests();
      }
  };

  if (!user?.isRider) {
    return (
        <div className="container mx-auto px-4 py-20 text-center">
            <h2 className="text-2xl font-bold text-slate-800">Access Denied</h2>
            <p className="text-slate-500 mb-6">This area is restricted to registered Delivery Riders.</p>
            <Link to="/" className="text-brand-600 font-bold hover:underline">Return Home</Link>
        </div>
    );
  }

  return (
    <div className="container mx-auto px-4 pt-12 pb-20"> {/* Standardized padding with gap */}
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
         <div>
            <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
               <Icon name="truck" size={32} className="text-brand-600" /> Rider Dashboard
            </h1>
            <p className="text-slate-500">Welcome back, {user.name}</p>
         </div>

         <div className={`flex items-center gap-3 px-4 py-2 rounded-full border shadow-sm transition-all ${isOnline ? 'bg-green-50 border-green-200 text-green-700' : 'bg-slate-50 border-slate-200 text-slate-500'}`}>
            <span className={`w-3 h-3 rounded-full ${isOnline ? 'bg-green-500 animate-pulse' : 'bg-slate-400'}`}></span>
            <span className="font-bold text-sm uppercase tracking-wider">{isOnline ? 'Online' : 'Offline'}</span>
            <button 
                onClick={() => setIsOnline(!isOnline)} 
                className="ml-2 text-xs underline hover:no-underline font-medium"
            >
                {isOnline ? 'Go Offline' : 'Go Online'}
            </button>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         {/* LEFT COL: Active Job */}
         <div className="lg:col-span-2 space-y-6">
            <h2 className="text-xl font-bold text-slate-800">Current Assignment</h2>

            {activeRequest ? (
               <div className="bg-white rounded-3xl shadow-xl border border-brand-100 overflow-hidden relative">
                   <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-500 to-fuchsia-500"></div>
                   <div className="p-6 md:p-8">
                       <div className="flex flex-col md:flex-row gap-6 mb-8">
                           <div className="w-full md:w-1/3 aspect-square rounded-2xl overflow-hidden bg-slate-100 border border-slate-200">
                               <img src={activeRequest.listingImage} alt="Item" className="w-full h-full object-cover" />
                           </div>
                           <div className="flex-1 space-y-4">
                               <div className="flex justify-between items-start">
                                  <div>
                                     <span className="inline-block px-3 py-1 bg-brand-100 text-brand-700 text-xs font-bold rounded-lg mb-2 uppercase tracking-wide">
                                         {activeRequest.status.replace('_', ' ')}
                                     </span>
                                     <h3 className="text-2xl font-bold text-slate-900">{activeRequest.listingTitle}</h3>
                                  </div>
                                  <Link to={`/chat?to=${activeRequest.buyerId}`} className="p-3 bg-slate-100 text-slate-600 rounded-xl hover:bg-brand-500 hover:text-white transition-all">
                                      <Icon name="messageCircle" size={20} />
                                  </Link>
                               </div>

                               <div className="space-y-3 pt-2">
                                   <div className="flex items-start gap-3 p-3 bg-slate-50 rounded-xl">
                                      <Icon name="mapPin" size={20} className="text-red-500 mt-1" />
                                      <div>
                                         <p className="text-xs font-bold text-slate-400 uppercase">Pickup From</p>
                                         <p className="font-semibold text-slate-800">{activeRequest.pickupAddress}</p>
                                      </div>
                                   </div>
                                   <div className="flex items-start gap-3 p-3 bg-slate-50 rounded-xl">
                                      <Icon name="mapPin" size={20} className="text-green-500 mt-1" />
                                      <div>
                                         <p className="text-xs font-bold text-slate-400 uppercase">Deliver To</p>
                                         <p className="font-semibold text-slate-800">{activeRequest.dropoffAddress}</p>
                                      </div>
                                   </div>
                               </div>
                           </div>
                       </div>

                       {/* Action Area */}
                       <div className="border-t border-slate-100 pt-6">
                           {activeRequest.status === 'NEGOTIATING' && (
                               <div className="bg-amber-50 border border-amber-200 rounded-2xl p-6">
                                   <h4 className="font-bold text-amber-800 mb-2">Step 1: Negotiate Fee</h4>
                                   <p className="text-sm text-amber-700 mb-4">Chat with the buyer to agree on a price, then enter it here to confirm.</p>
                                   <div className="flex gap-4">
                                       <div className="relative flex-1">
                                           <span className="absolute left-4 top-1/2 -translate-y-1/2 font-bold text-slate-500">$</span>
                                           <input 
                                             type="number" 
                                             value={feeInput}
                                             onChange={(e) => setFeeInput(e.target.value)}
                                             className="w-full pl-8 pr-4 py-3 rounded-xl border border-amber-200 outline-none focus:ring-2 focus:ring-amber-500 bg-white"
                                             placeholder="0.00"
                                           />
                                       </div>
                                       <button 
                                          onClick={handleUpdateFee}
                                          disabled={!feeInput}
                                          className="bg-amber-500 text-white px-6 py-3 rounded-xl font-bold hover:bg-amber-600 transition-colors disabled:opacity-50"
                                       >
                                           Confirm Fee
                                       </button>
                                   </div>
                               </div>
                           )}

                           {activeRequest.status === 'ACCEPTED' && (
                               <div className="bg-blue-50 border border-blue-200 rounded-2xl p-6 flex flex-col items-center text-center">
                                   <h4 className="font-bold text-blue-800 mb-2">Step 2: Pickup</h4>
                                   <p className="text-sm text-blue-700 mb-4">Proceed to the vendor location. Confirm when you have the item.</p>
                                   <button 
                                      onClick={() => handleStatusUpdate('PICKED_UP')}
                                      className="w-full bg-blue-600 text-white px-6 py-4 rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-500/20"
                                   >
                                       Confirm Pickup
                                   </button>
                               </div>
                           )}

                           {activeRequest.status === 'PICKED_UP' && (
                               <div className="bg-green-50 border border-green-200 rounded-2xl p-6 flex flex-col items-center text-center">
                                   <h4 className="font-bold text-green-800 mb-2">Step 3: Delivery</h4>
                                   <p className="text-sm text-green-700 mb-4">Head to the buyer. Collect cash (if applicable) and confirm delivery.</p>
                                   <div className="text-3xl font-bold text-slate-800 mb-4">${activeRequest.fee}</div>
                                   <button 
                                      onClick={() => handleStatusUpdate('DELIVERED')}
                                      className="w-full bg-green-600 text-white px-6 py-4 rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-500/20 animate-pulse"
                                   >
                                       Mark as Delivered
                                   </button>
                               </div>
                           )}
                       </div>
                   </div>
               </div>
            ) : (
                <div className="bg-white rounded-3xl border border-slate-200 p-12 text-center">
                    <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-400">
                        <Icon name="truck" size={40} />
                    </div>
                    <h3 className="text-xl font-bold text-slate-800 mb-2">No Active Deliveries</h3>
                    <p className="text-slate-500">Wait for new requests to appear in the panel.</p>
                </div>
            )}
         </div>

         {/* RIGHT COL: Requests & History */}
         <div className="space-y-6">
             {/* Pending Requests */}
             <div className="glass rounded-3xl p-6 shadow-lg border border-white/50">
                 <div className="flex justify-between items-center mb-4">
                    <h2 className="font-bold text-slate-800">New Requests</h2>
                    <span className="bg-brand-100 text-brand-600 text-xs font-bold px-2 py-1 rounded-full">{requests.filter(r => r.status === 'PENDING').length}</span>
                 </div>

                 <div className="space-y-3 max-h-[300px] overflow-y-auto custom-scrollbar">
                     {requests.filter(r => r.status === 'PENDING').map(req => (
                         <div key={req.id} className="bg-white/80 p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all">
                             <div className="flex gap-3 mb-3">
                                <img src={req.listingImage} className="w-12 h-12 rounded-lg object-cover" />
                                <div>
                                    <h4 className="font-bold text-sm text-slate-900 line-clamp-1">{req.listingTitle}</h4>
                                    <p className="text-xs text-slate-500">{req.pickupAddress.split(',')[0]}</p>
                                </div>
                             </div>
                             <div className="flex gap-2">
                                <button onClick={() => handleAccept(req)} className="flex-1 bg-brand-600 text-white text-xs font-bold py-2 rounded-lg hover:bg-brand-700">Accept</button>
                                <button className="px-3 bg-slate-100 text-slate-600 text-xs font-bold rounded-lg hover:bg-slate-200">Ignore</button>
                             </div>
                         </div>
                     ))}
                     {requests.filter(r => r.status === 'PENDING').length === 0 && (
                         <p className="text-center text-sm text-slate-500 py-4 italic">No pending requests in your area.</p>
                     )}
                 </div>
             </div>

             {/* History (Mock) */}
             <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-200">
                 <h2 className="font-bold text-slate-800 mb-4">Recent History</h2>
                 <div className="space-y-4">
                     {[1,2,3].map(i => (
                         <div key={i} className="flex items-center justify-between text-sm">
                             <div className="flex items-center gap-3">
                                 <div className="w-8 h-8 rounded-full bg-green-100 text-green-600 flex items-center justify-center">
                                     <Icon name="check" size={14} />
                                 </div>
                                 <div>
                                     <p className="font-bold text-slate-800">Delivery #{1000+i}</p>
                                     <p className="text-xs text-slate-400">2 days ago</p>
                                 </div>
                             </div>
                             <span className="font-bold text-slate-900">$25.00</span>
                         </div>
                     ))}
                 </div>
             </div>
         </div>
      </div>
    </div>
  );
};

export default RiderDashboard;

