import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getListingById, getUser, createChat, createDeliveryRequest } from '../services/mockData';
import { Listing, User } from '../types';
import Icon from '../components/Icon';
import { draftBuyerMessage } from '../services/ai';
import { useLocation } from '../context/LocationContext';
import { useAuth } from '../context/AuthContext';
import SafetyDisclaimer from '../components/SafetyDisclaimer';

const ListingDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [listing, setListing] = useState<Listing | undefined>(undefined);
  const [seller, setSeller] = useState<User | undefined>(undefined);
  const [message, setMessage] = useState('');
  const [isAiDrafting, setIsAiDrafting] = useState(false);
  const [deliveryRequested, setDeliveryRequested] = useState(false);
  const { convertPrice } = useLocation();

  // Safety Modal State
  const [showSafetyModal, setShowSafetyModal] = useState(false);
  const [pendingAction, setPendingAction] = useState<(() => void) | null>(null);

  useEffect(() => {
    if (id) {
      const data = getListingById(id);
      setListing(data);
      if (data && data.sellerId) {
         setSeller(getUser(data.sellerId));
      }
    }
  }, [id]);

  const handleAiDraft = async (intent: string) => {
    if (!listing) return;
    setIsAiDrafting(true);
    const draft = await draftBuyerMessage(intent, listing.title);
    setMessage(draft);
    setIsAiDrafting(false);
  };

  const handleStartChat = () => {
    if (listing && seller) {
      // Create chat with 'user-me' (current user) and seller
      const chatId = createChat('user-me', seller.id, listing.id);
      navigate(`/chat?id=${chatId}`);
    }
  };

  const initiateSafetyCheck = (action: () => void) => {
      setPendingAction(() => action);
      setShowSafetyModal(true);
  };

  const handleSafetyConfirmed = () => {
      setShowSafetyModal(false);
      if (pendingAction) {
          pendingAction();
          setPendingAction(null);
      }
  };

  const executeDeliveryRequest = () => {
      if (!user) {
          navigate('/signin', { state: { from: { pathname: `/listing/${id}` } } });
          return;
      }
      if (listing) {
          setDeliveryRequested(true);
          createDeliveryRequest(listing, user.id);
          // Auto-start chat with seller to notify them
          createChat(user.id, listing.sellerId, listing.id);

          setTimeout(() => setDeliveryRequested(false), 3000); // Reset after 3s
      }
  };

  const executeWhatsApp = () => {
    if (seller?.socials.whatsapp) {
      window.open(`https://wa.me/${seller.socials.whatsapp}`, '_blank');
    } else {
      alert("This seller hasn't provided a WhatsApp number.");
    }
  };

  if (!listing) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh]">
        <div className="animate-spin text-brand-500 mb-4"><Icon name="loader" size={32} /></div>
        <p className="text-slate-500">Loading details...</p>
      </div>
    );
  }

  const convertedPrice = convertPrice(listing.price);

  return (
    <div className="container mx-auto px-4 pt-6 pb-8 animate-fade-in relative">
      {/* Safety Modal */}
      <SafetyDisclaimer 
        isOpen={showSafetyModal} 
        onClose={() => setShowSafetyModal(false)} 
        onConfirm={handleSafetyConfirmed} 
      />

      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-slate-500 mb-6">
        <Link to="/" className="hover:text-brand-600">Home</Link>
        <Icon name="chevronRight" size={12} />
        <Link to={`/category/${listing.categoryId}`} className="hover:text-brand-600 capitalize">{listing.categoryId.replace('-', ' ')}</Link>
        <Icon name="chevronRight" size={12} />
        <span className="text-slate-900 truncate max-w-[200px]">{listing.title}</span>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Images & Info */}
        <div className="lg:col-span-2 space-y-8">
          {/* Image Gallery */}
          <div className="bg-slate-100 rounded-3xl overflow-hidden aspect-video relative group">
            <img src={listing.imageUrl} alt={listing.title} className="w-full h-full object-cover" />
            <div className="absolute top-4 right-4">
               <button className="bg-white/90 backdrop-blur p-2.5 rounded-full text-slate-400 hover:text-red-500 transition-colors shadow-lg">
                 <Icon name="heart" size={24} />
               </button>
            </div>
            {listing.isFeatured && (
               <div className="absolute top-4 left-4 bg-yellow-400 text-yellow-900 text-xs font-bold px-3 py-1.5 rounded-lg shadow-lg uppercase tracking-wider">
                 Featured Pick
               </div>
            )}
          </div>

          {/* Details */}
          <div className="bg-white rounded-3xl p-8 border border-slate-100 shadow-sm">
             <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 border-b border-slate-100 pb-6">
                <div>
                   <h1 className="text-2xl md:text-3xl font-bold text-slate-900 mb-2">{listing.title}</h1>
                   <div className="flex items-center gap-4 text-sm text-slate-500">
                      <span className="flex items-center gap-1"><Icon name="mapPin" size={16} /> {listing.location}</span>
                      <span className="flex items-center gap-1"><Icon name="activity" size={16} /> Posted {listing.datePosted}</span>
                   </div>
                </div>
                <div className="text-3xl font-bold text-brand-600">
                   {convertedPrice.symbol}{convertedPrice.formatted}
                </div>
             </div>

             <div className="space-y-4">
                <h3 className="font-bold text-lg text-slate-900">Description</h3>
                <p className="text-slate-600 leading-relaxed">
                   This is a placeholder description for the item. In a real application, this would be fetched from the backend. 
                   The item is located in {listing.location} and is available for immediate purchase.
                   Excellent condition, barely used. Comes with original packaging and all accessories.
                </p>
                <div className="flex gap-2 flex-wrap mt-4">
                   {['Verified Seller', 'Fast Response', 'Negotiable'].map(tag => (
                      <span key={tag} className="px-3 py-1 bg-slate-100 text-slate-600 rounded-full text-xs font-medium">
                         {tag}
                      </span>
                   ))}
                </div>
             </div>
          </div>
        </div>

        {/* Right Column: Contact & Action */}
        <div className="lg:col-span-1">
           <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-xl shadow-slate-200/50 sticky top-24">
              {seller ? (
                <div className="flex items-center gap-4 mb-6 pb-6 border-b border-slate-100">
                  <Link to={`/profile/${seller.id}`} className="block relative group flex-shrink-0">
                    <img src={seller.avatar} alt={seller.name} className="w-16 h-16 rounded-full object-cover border-2 border-brand-100 group-hover:border-brand-500 transition-colors shadow-sm" />
                    {seller.verified && (
                       <div className="absolute -bottom-1 -right-1 bg-brand-500 text-white p-1 rounded-full border-2 border-white">
                          <Icon name="check" size={10} />
                       </div>
                    )}
                  </Link>
                  <div className="min-w-0">
                    <Link to={`/profile/${seller.id}`} className="font-bold text-slate-900 hover:text-brand-600 text-lg flex items-center gap-2 truncate">
                        {seller.name}
                        {seller.verified && (
                            <span className="flex-shrink-0 bg-brand-100 text-brand-600 text-[10px] px-2 py-0.5 rounded-full border border-brand-200 flex items-center gap-1 uppercase tracking-wider font-bold">
                                <Icon name="check" size={10} /> Verified
                            </span>
                        )}
                    </Link>

                    {/* Seller Location */}
                    <div className="flex items-center gap-1.5 text-xs text-slate-500 mb-1">
                        <Icon name="mapPin" size={12} className="text-slate-400" />
                        <span className="truncate">{seller.location}</span>
                    </div>

                    <div className="flex items-center gap-1 text-xs text-brand-600 mb-2">
                        <Icon name="star" size={12} className="fill-brand-600" /> 
                        <span className="font-semibold">{seller.rating}</span>
                        <span className="text-slate-400 font-normal">({seller.reviewCount} reviews)</span>
                    </div>

                    <p className="text-xs text-slate-500 line-clamp-1 mb-3">{seller.bio}</p>

                    {/* Contact Icons */}
                    <div className="flex gap-2 flex-wrap">
                       {seller.socials.phone && (
                          <a href={`tel:${seller.socials.phone}`} className="w-8 h-8 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-emerald-100" title="Call">
                             <Icon name="phone" size={14} />
                          </a>
                       )}
                       {seller.socials.email && (
                          <a href={`mailto:${seller.socials.email}`} className="w-8 h-8 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center hover:bg-blue-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-blue-100" title="Email">
                             <Icon name="mail" size={14} />
                          </a>
                       )}
                       {seller.socials.website && (
                          <a href={seller.socials.website.startsWith('http') ? seller.socials.website : `https://${seller.socials.website}`} target="_blank" rel="noopener noreferrer" className="w-8 h-8 rounded-full bg-purple-50 text-purple-600 flex items-center justify-center hover:bg-purple-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-purple-100" title="Website">
                             <Icon name="globe" size={14} />
                          </a>
                       )}

                       {/* Socials Separator if both exist */}
                       {(seller.socials.phone || seller.socials.email || seller.socials.website) && (seller.socials.facebook || seller.socials.instagram || seller.socials.twitter || seller.socials.linkedin) && (
                           <div className="w-px bg-slate-200 mx-1 h-6 self-center"></div>
                       )}

                       {seller.socials.facebook && <a href={`https://facebook.com/${seller.socials.facebook}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-[#1877F2] hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="facebook" size={14} /></a>}
                       {seller.socials.instagram && <a href={`https://instagram.com/${seller.socials.instagram}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-pink-600 hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="instagram" size={14} /></a>}
                       {seller.socials.twitter && <a href={`https://twitter.com/${seller.socials.twitter}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-sky-500 hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="twitter" size={14} /></a>}
                       {seller.socials.linkedin && <a href={`https://linkedin.com/in/${seller.socials.linkedin}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-slate-50 text-slate-500 flex items-center justify-center hover:bg-blue-700 hover:text-white transition-all hover:scale-110 shadow-sm border border-slate-200"><Icon name="linkedin" size={14} /></a>}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="mb-6 pb-6 border-b border-slate-100">
                  <div className="animate-pulse flex items-center gap-4">
                     <div className="w-16 h-16 bg-slate-200 rounded-full"></div>
                     <div className="flex-1 space-y-2">
                        <div className="h-4 bg-slate-200 rounded w-3/4"></div>
                        <div className="h-3 bg-slate-200 rounded w-1/2"></div>
                     </div>
                  </div>
                </div>
              )}

              <div className="space-y-4">
                 {/* BUY WITH DELIVERY BUTTON */}
                 <button 
                    onClick={() => initiateSafetyCheck(executeDeliveryRequest)}
                    disabled={deliveryRequested}
                    className="w-full bg-gradient-to-r from-violet-600 to-indigo-600 text-white py-4 rounded-xl font-bold hover:shadow-lg hover:shadow-violet-500/25 transition-all flex items-center justify-center gap-3 transform hover:-translate-y-0.5 disabled:opacity-80 disabled:cursor-not-allowed"
                 >
                    {deliveryRequested ? (
                        <>
                            <Icon name="check" size={20} /> Request Sent!
                        </>
                    ) : (
                        <>
                            <Icon name="truck" size={20} /> Buy with Delivery
                        </>
                    )}
                 </button>

                 {/* WhatsApp Button */}
                 <button 
                    onClick={() => initiateSafetyCheck(executeWhatsApp)}
                    className="w-full bg-[#25D366] text-white py-3.5 rounded-xl font-bold hover:bg-[#128C7E] transition-colors shadow-lg shadow-green-500/20 flex items-center justify-center gap-2"
                 >
                    <Icon name="whatsapp" size={20} />
                    WhatsApp Seller
                 </button>

                 <div className="relative">
                    <div className="absolute -top-3 left-4 px-2 bg-white text-xs font-bold text-brand-500 flex items-center gap-1">
                      <Icon name="menu" size={10} /> AI Assistant
                    </div>
                    <div className="border border-brand-100 rounded-xl p-4 bg-brand-50/30">
                       <p className="text-xs text-slate-500 mb-3">Quickly draft a message:</p>
                       <div className="flex gap-2 mb-3 overflow-x-auto pb-2 custom-scrollbar">
                          <button onClick={() => handleAiDraft('Is it available?')} className="whitespace-nowrap px-3 py-1.5 bg-white border border-brand-200 rounded-lg text-xs font-medium text-brand-700 hover:bg-brand-50 transition-colors">
                             Is it available?
                          </button>
                          <button onClick={() => handleAiDraft('Negotiate price')} className="whitespace-nowrap px-3 py-1.5 bg-white border border-brand-200 rounded-lg text-xs font-medium text-brand-700 hover:bg-brand-50 transition-colors">
                             Negotiate
                          </button>
                          <button onClick={() => handleAiDraft('Ask condition')} className="whitespace-nowrap px-3 py-1.5 bg-white border border-brand-200 rounded-lg text-xs font-medium text-brand-700 hover:bg-brand-50 transition-colors">
                             Condition?
                          </button>
                       </div>

                       <textarea 
                          value={message}
                          onChange={(e) => setMessage(e.target.value)}
                          className={`w-full p-3 rounded-lg border text-sm focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none resize-none ${isAiDrafting ? 'bg-slate-100 animate-pulse' : 'bg-white border-slate-200'}`}
                          rows={3}
                          placeholder="Hi, I'm interested in..."
                       ></textarea>
                       <button 
                         onClick={handleStartChat}
                         className="w-full mt-3 bg-white border border-slate-300 text-slate-700 py-2.5 rounded-xl font-bold hover:bg-brand-50 hover:text-brand-600 hover:border-brand-200 transition-all flex items-center justify-center gap-2"
                       >
                          <Icon name="messageCircle" size={18} />
                          Send Message
                       </button>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      </div>

      {deliveryRequested && (
          <div className="fixed bottom-10 right-10 bg-slate-900 text-white p-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-slide-up z-50">
              <div className="w-10 h-10 rounded-full bg-green-500 flex items-center justify-center text-white">
                  <Icon name="check" size={20} />
              </div>
              <div>
                  <h4 className="font-bold">Request Sent</h4>
                  <p className="text-sm text-slate-400">Notifying vendor and riders...</p>
              </div>
          </div>
      )}
    </div>
  );
};

export default ListingDetails;

import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { CATEGORIES } from '../constants';
import ListingCard from '../components/ListingCard';
import { generateListings } from '../services/mockData';
import Icon from '../components/Icon';

const ITEMS_PER_BATCH = 40; // 8 rows * 5 columns = 40 items

const CategoryPage: React.FC = () => {
  const { categoryId } = useParams<{ categoryId: string }>();

  // Data State
  const [listings, setListings] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Filter State
  const [selectedSubcats, setSelectedSubcats] = useState<string[]>([]);
  const [isSubcatOpen, setIsSubcatOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const category = CATEGORIES.find(c => c.id === categoryId);

  // Reset and load initial batch when category changes
  useEffect(() => {
    if (categoryId) {
      const initialListings = generateListings(categoryId, ITEMS_PER_BATCH, 0);
      setListings(initialListings);
      setSelectedSubcats([]); // Reset filters on category change
    }
  }, [categoryId]);

  // Handle click outside to close dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsSubcatOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLoadMore = () => {
    if (!categoryId) return;

    setIsLoading(true);
    // Simulate network delay for realistic feel
    setTimeout(() => {
      const nextBatch = generateListings(categoryId, ITEMS_PER_BATCH, listings.length);
      setListings(prev => [...prev, ...nextBatch]);
      setIsLoading(false);
    }, 800);
  };

  const toggleSubcat = (id: string) => {
    setSelectedSubcats(prev => 
      prev.includes(id) ? prev.filter(sid => sid !== id) : [...prev, id]
    );
  };

  const clearSubcats = () => setSelectedSubcats([]);

  if (!category) {
    return (
      <div className="container mx-auto px-4 py-20 text-center">
        <h2 className="text-2xl font-bold text-slate-800">Category not found</h2>
        <Link to="/" className="text-brand-600 mt-4 inline-block">Go Home</Link>
      </div>
    );
  }

  // NOTE: In a real app, we would filter 'listings' based on 'selectedSubcats' here.
  // Since our mock data generator doesn't assign subcategory IDs, we display all generated listings.
  // Visual feedback for filtering is provided by the UI elements.
  const displayListings = listings; 

  return (
    <div className="bg-brand-50 min-h-screen pb-8 pt-4"> {/* Standardized padding with reduced gap */}
      {/* Header Breadcrumb Area */}
      <div className="bg-white border-b border-slate-200">
        <div className="container mx-auto px-4 py-8">
           <div className="text-sm text-slate-500 mb-2 flex items-center gap-2">
              <Link to="/" className="hover:text-brand-600">Home</Link>
              <Icon name="chevronRight" size={14} />
              <span className="font-medium text-slate-900">{category.name}</span>
           </div>
           <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
              <div className={`p-2 rounded-xl ${category.color.replace('text-', 'bg-').replace('bg-', 'text-white ')} bg-opacity-90`}>
                 <img src={category.icon3d} alt="" className="w-8 h-8 object-contain animate-icon-float" />
              </div>
              {category.name} Listings
           </h1>
        </div>
      </div>

      <div className="container mx-auto px-4 py-6">
        {/* Modern Filter Bar */}
        <div className="bg-white rounded-2xl p-4 md:p-6 shadow-sm border border-slate-200 mb-8 transition-all">

           <div className="flex flex-col lg:flex-row gap-6 lg:items-center justify-between">

              {/* Left Side: Subcategories & Price */}
              <div className="flex flex-col md:flex-row gap-4 w-full lg:w-auto">

                {/* Subcategory Multi-Select Dropdown */}
                <div className="relative" ref={dropdownRef}>
                   <button 
                     onClick={() => setIsSubcatOpen(!isSubcatOpen)}
                     className={`flex items-center gap-2 px-4 py-3 rounded-xl border transition-all text-sm font-bold min-w-[220px] justify-between ${isSubcatOpen || selectedSubcats.length > 0 ? 'border-brand-500 bg-brand-50 text-brand-700 ring-2 ring-brand-100 shadow-sm' : 'border-slate-200 bg-white text-slate-700 hover:border-slate-300 hover:bg-slate-50'}`}
                   >
                     <span className="flex items-center gap-2">
                       <Icon name="sliders" size={16} />
                       {selectedSubcats.length > 0 ? `${selectedSubcats.length} Subcategories` : 'Subcategories'}
                     </span>
                     <Icon name="chevronRight" size={14} className={`transition-transform duration-200 ${isSubcatOpen ? '-rotate-90' : 'rotate-90'}`} />
                   </button>

                   {/* Dropdown Menu */}
                   {isSubcatOpen && (
                     <div className="absolute top-full left-0 mt-2 w-72 bg-white rounded-2xl shadow-[0_10px_40px_-10px_rgba(0,0,0,0.1)] border border-slate-100 p-3 z-50 animate-fade-in">
                        <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 px-2">Select Options</div>
                        <div className="max-h-64 overflow-y-auto custom-scrollbar space-y-1">
                          {category.subcategories.map(sub => (
                            <label key={sub.id} className="flex items-center gap-3 p-2.5 rounded-xl hover:bg-slate-50 cursor-pointer group transition-colors select-none">
                              <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-all ${selectedSubcats.includes(sub.id) ? 'bg-brand-600 border-brand-600' : 'border-slate-300 bg-white group-hover:border-brand-400'}`}>
                                {selectedSubcats.includes(sub.id) && <Icon name="check" size={12} className="text-white" />}
                              </div>
                              <span className={`text-sm ${selectedSubcats.includes(sub.id) ? 'font-bold text-brand-700' : 'text-slate-600'}`}>{sub.name}</span>
                              <input 
                                type="checkbox" 
                                className="hidden" 
                                checked={selectedSubcats.includes(sub.id)}
                                onChange={() => toggleSubcat(sub.id)}
                              />
                            </label>
                          ))}
                        </div>
                        <div className="border-t border-slate-100 mt-2 pt-2 flex justify-between px-1">
                           <button onClick={clearSubcats} className="text-xs text-slate-500 hover:text-red-500 font-bold px-2 py-1.5 rounded hover:bg-red-50 transition-colors">Clear All</button>
                           <button onClick={() => setIsSubcatOpen(false)} className="text-xs text-white bg-brand-600 font-bold px-4 py-1.5 rounded-lg hover:bg-brand-700 transition-colors shadow-sm">Done</button>
                        </div>
                     </div>
                   )}
                </div>

                {/* Price Filter */}
                <div className="flex items-center gap-0 bg-slate-50 rounded-xl border border-slate-200 p-1 pl-3 overflow-hidden focus-within:ring-2 focus-within:ring-brand-100 focus-within:border-brand-300 transition-all">
                   <span className="text-xs font-bold text-slate-400 uppercase mr-2 flex items-center gap-1"><Icon name="coins" size={12} /> Price</span>
                   <input type="number" placeholder="Min" className="w-16 bg-transparent text-sm font-bold text-slate-700 outline-none placeholder:font-medium placeholder:text-slate-400 text-center" />
                   <span className="text-slate-300 mx-1">-</span>
                   <input type="number" placeholder="Max" className="w-16 bg-transparent text-sm font-bold text-slate-700 outline-none placeholder:font-medium placeholder:text-slate-400 text-center" />
                </div>

              </div>

              {/* Right Side: Sort */}
              <div className="flex items-center gap-3 w-full lg:w-auto justify-end">
                 <span className="text-sm font-bold text-slate-500 whitespace-nowrap hidden sm:inline">Sort by:</span>
                 <div className="relative w-full sm:w-48">
                    <select className="appearance-none w-full border border-slate-200 bg-white rounded-xl px-4 py-3 pr-10 text-sm font-bold text-slate-700 focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none cursor-pointer hover:border-slate-300 transition-colors shadow-sm">
                        <option>Newest First</option>
                        <option>Price: Low to High</option>
                        <option>Price: High to Low</option>
                        <option>Most Popular</option>
                    </select>
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                        <Icon name="chevronRight" size={12} className="rotate-90" />
                    </div>
                 </div>
              </div>
           </div>

           {/* Active Filters Tags */}
           {selectedSubcats.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-5 pt-5 border-t border-slate-100 animate-fade-in">
                 <span className="text-xs font-bold text-slate-400 uppercase py-1.5 self-center mr-2">Active Filters:</span>
                 {selectedSubcats.map(id => {
                    const sub = category.subcategories.find(s => s.id === id);
