import FuturisticBackground from './FuturisticBackground';
import { useAuth } from '../context/AuthContext';
import { useLocation as useAppLocation } from '../context/LocationContext';
import { CATEGORIES } from '../constants';
import AdBanner from './AdBanner';
import AdvertisementPopup from './AdvertisementPopup';

interface LayoutProps {
  children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const currentYear = new Date().getFullYear();
  const navigate = useNavigate();
  const location = useLocation();
  const { user, isAuthenticated } = useAuth();
  const { location: userLocData, refreshLocation, isLoading: isLocating } = useAppLocation();
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [isPaused, setIsPaused] = useState(false);

  // Duplicate categories for seamless infinite scroll
  const displayCategories = [...CATEGORIES, ...CATEGORIES];

  const handleManualLocate = () => {
    refreshLocation();
  };

  const scroll = (direction: 'left' | 'right') => {
    if (scrollContainerRef.current) {
        const { current } = scrollContainerRef;
        const scrollAmount = 300; 
        if (direction === 'left') {
            current.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
        } else {
            current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
        }
    }
  };

  // Auto-scroll logic
  useEffect(() => {
    // Scroll everywhere now
    const container = scrollContainerRef.current;
    if (!container) return;

    const interval = setInterval(() => {
      if (!isPaused && container) {
        // Continuous scroll - Speed increased
        // Moving 2 pixels per tick makes it visibly faster and smoother than 1px
        container.scrollLeft += 2;

        // Seamless Loop: Reset to 0 when we reach the start of the second set (halfway point)
        // Since the list is duplicated, the first half is identical to the second half.
        // We add a small buffer check to ensure we catch the crossover point
        if (container.scrollLeft >= (container.scrollWidth / 2) - 2) {
             container.scrollLeft = 0;
        }
      }
    }, 20); // 20ms interval (approx 50fps) for smooth motion

    return () => clearInterval(interval);
  }, [isPaused]);

  const handleSearch = (query: string, filters?: SearchFilters) => {
    console.log("Searching for:", query, filters);

    // Check filter overrides
    if (filters?.categoryId) {
      navigate(`/category/${filters.categoryId}`);
      return;
    }

    if(query.toLowerCase().includes('car') || query.toLowerCase().includes('vehicle')) {
        navigate('/category/vehicles');
    } else if (query.toLowerCase().includes('phone') || query.toLowerCase().includes('laptop')) {
        navigate('/category/electronics');
    } else if (query.toLowerCase().includes('house') || query.toLowerCase().includes('rent')) {
        navigate('/category/real-estate');
    } else {
        navigate('/category/miscellaneous');
    }
  };

  return (
    <div className="min-h-screen flex flex-col relative overflow-x-hidden bg-brand-50">
      {/* 3D Animated Background */}
      <FuturisticBackground />

      {/* Global Auto Popup (Placed here for correct Z-Index stacking over header) */}
      <AdvertisementPopup />

      {/* Unified Floating Header Card */}
      <header className="sticky top-0 z-[100] pt-4 pb-2 pointer-events-none transition-all duration-300">
        <div className="container mx-auto px-4">
            <div className="pointer-events-auto w-full glass-card rounded-[2rem] transition-all relative overflow-hidden">

            {/* Top Bar: Brand, Search, Actions */}
            <div className="flex items-center justify-between px-4 sm:px-6 py-3 gap-4 md:gap-8 h-[72px]">

                {/* Logo */}
                <Link to="/" className="flex-shrink-0 hover:opacity-80 transition-opacity">
                    <Logo />
                </Link>

                {/* Search - Centered */}
                <div className="hidden md:block flex-1 max-w-xl">
                    <SmartSearchInput 
                    variant="simple" 
                    placeholder="Search classifieds..." 
                    onSearch={handleSearch}
                    className="w-full"
                    />
                </div>

                {/* Actions */}
                <div className="flex items-center gap-3 sm:gap-4 flex-shrink-0">

                    {/* Location (Hidden on mobile) */}
                    <button 
                    onClick={handleManualLocate}
                    className="hidden xl:flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-medium text-slate-500 hover:bg-brand-50 hover:text-brand-600 transition-all"
                    title="Update Location"
                    >
                    <Icon name="mapPin" size={14} className={`text-brand-500 ${isLocating ? 'animate-bounce' : ''}`} />
                    <span className="truncate max-w-[100px]">{userLocData.formattedAddress || "Location"}</span>
                    </button>

                    {/* Rider Dashboard Link (If Rider) */}
                    {isAuthenticated && user?.isRider && (
                        <Link 
                        to="/rider-dashboard" 
                        className="flex items-center gap-2 bg-slate-800 hover:bg-slate-900 text-white px-3 py-2.5 rounded-xl font-bold transition-all"
                        >
                        <Icon name="truck" size={18} />
                        <span className="hidden sm:inline">Rider Panel</span>
                        </Link>
                    )}

                    {/* Post Button (Hidden if rider for clean UX, or keep it) */}
                    {!user?.isRider && (
                        <Link 
                        to="/post" 
                        className="flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white px-5 py-2.5 rounded-xl font-bold transition-all shadow-lg shadow-brand-500/30 active:scale-95"
                        >
                        <Icon name="plus" size={18} strokeWidth={3} />
                        <span>Post</span>
                        </Link>
                    )}

                    {/* Auth */}
                    {isAuthenticated ? (
                    <div className="flex items-center gap-2">
                        <Link to="/chat" className="p-2 text-slate-500 hover:text-brand-600 hover:bg-brand-50 rounded-full transition-all relative group">
                        <Icon name="messageCircle" size={22} />
                        <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 border border-white rounded-full"></span>
                        </Link>
                        <Link to="/profile/me" className="w-10 h-10 rounded-full bg-slate-100 p-0.5 border border-slate-200 cursor-pointer hover:ring-2 hover:ring-brand-200 transition-all">
                        <img src={user?.avatar || 'https://via.placeholder.com/150'} alt="User" className="w-full h-full rounded-full object-cover" />
                        </Link>
                    </div>
                    ) : (
                    <Link 
                        to="/signin" 
                        className="font-bold text-sm text-slate-600 hover:text-slate-900 px-2 transition-colors"
                    >
                        Sign In
                    </Link>
                    )}

                    {/* Mobile Menu Toggle */}
                    <button className="md:hidden p-2 text-slate-500 hover:bg-brand-50 rounded-full">
                    <Icon name="menu" size={24} />
                    </button>
                </div>
            </div>

            {/* Categories Row - Visible on all pages */}
            <div 
                className="relative border-t border-purple-100/50 pb-2 group/cat-nav"
                onMouseEnter={() => setIsPaused(true)}
                onMouseLeave={() => setIsPaused(false)}
                onTouchStart={() => setIsPaused(true)}
                onTouchEnd={() => setIsPaused(false)}
            >
            {/* Fade Masks */}
            <div className="absolute left-0 top-0 bottom-0 w-12 bg-gradient-to-r from-white to-transparent z-10 pointer-events-none"></div>
            <div className="absolute right-0 top-0 bottom-0 w-12 bg-gradient-to-l from-white to-transparent z-10 pointer-events-none"></div>

            {/* Navigation Buttons (Swipe Buttons) */}
            <button 
                onClick={() => scroll('left')}
                className="absolute left-2 top-1/2 -translate-y-1/2 z-20 w-8 h-8 rounded-full bg-white shadow-md border border-slate-100 flex items-center justify-center text-slate-600 hover:text-brand-600 hover:scale-110 transition-all opacity-0 group-hover/cat-nav:opacity-100 focus:opacity-100 active:scale-95 md:opacity-100"
                aria-label="Scroll left"
            >
                <Icon name="chevronRight" size={20} className="rotate-180" />
            </button>
            <button 
                onClick={() => scroll('right')}
                className="absolute right-2 top-1/2 -translate-y-1/2 z-20 w-8 h-8 rounded-full bg-white shadow-md border border-slate-100 flex items-center justify-center text-slate-600 hover:text-brand-600 hover:scale-110 transition-all opacity-0 group-hover/cat-nav:opacity-100 focus:opacity-100 active:scale-95 md:opacity-100"
                aria-label="Scroll right"
            >
                <Icon name="chevronRight" size={20} />
            </button>

            <div className="overflow-hidden py-3">
                <div 
                    ref={scrollContainerRef}
                    className="flex items-start gap-4 overflow-x-auto scroll-smooth no-scrollbar px-4"
                    style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
                >
                    {displayCategories.map((category, idx) => {
                        const isActive = location.pathname.includes(`/category/${category.id}`);
                        return (
                            <Link 
                            key={`${category.id}-${idx}`}
                            to={`/category/${category.id}`}
                            className="flex flex-col items-center gap-2 group cursor-pointer w-[90px] flex-shrink-0 transition-transform duration-300 hover:scale-105 relative"
                            >
                            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-300 shadow-sm border ${isActive ? 'bg-brand-100 border-brand-300 shadow-brand-200' : 'bg-slate-50 border-slate-100 group-hover:bg-brand-50 group-hover:border-brand-100'}`}>
                                <img 
                                    src={category.icon3d} 
                                    alt={category.name} 
                                    className={`w-9 h-9 object-contain drop-shadow-sm group-hover:scale-110 transition-transform ${isActive ? 'scale-110' : ''}`} 
                                    loading="lazy"
                                />
                            </div>
                            <span className={`text-[11px] font-bold text-center leading-tight transition-colors px-1 max-w-full break-words ${isActive ? 'text-brand-700' : 'text-slate-600 group-hover:text-brand-600'}`}>
                                {category.name}
                            </span>
                            </Link>
                        );
                    })}
                </div>
            </div>
            </div>

            {/* Search Mobile - Show only on mobile */}
            <div className="md:hidden px-4 pb-4">
                <SmartSearchInput variant="simple" onSearch={handleSearch} placeholder="Search..." />
            </div>

            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow relative z-0">
        {children}
      </main>

      {/* Global Ad Banner */}
      <AdBanner />

      {/* Footer */}
      <footer className="bg-brand-950 text-purple-100 py-6 mt-0 relative z-10">
        <div className="container mx-auto px-4 flex flex-col md:flex-row items-center justify-between gap-6 md:gap-4">

          {/* Brand Only (Copyright Removed) */}
          <div className="flex flex-col md:flex-row items-center gap-2 md:gap-8">
            <div className="scale-90 opacity-90 grayscale brightness-200">
                <Logo />
            </div>
          </div>

          {/* Contact & Socials */}
          <div className="flex flex-col sm:flex-row items-center gap-4 sm:gap-6">

            {/* Contact Info */}
            <div className="flex items-center gap-4 text-sm font-medium">
                <a href="mailto:support@tym2muv.com" className="flex items-center gap-2 text-purple-200 hover:text-white transition-colors group">
                    <div className="p-1.5 rounded-full bg-white/5 group-hover:bg-brand-600 transition-colors">
                        <Icon name="mail" size={14} />
                    </div>
                    <span className="hidden sm:inline">support@tym2muv.com</span>
                </a>
                <a href="https://wa.me/1234567890" target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 text-purple-200 hover:text-[#25D366] transition-colors group">
                    <div className="p-1.5 rounded-full bg-white/5 group-hover:bg-[#25D366] transition-colors">
                        <Icon name="whatsapp" size={14} />
                    </div>
                    <span className="hidden sm:inline">WhatsApp</span>
                </a>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default Layout;

