                                      </div>
                                   </div>
                               </div>
                           </div>
                       </div>

                       {/* Action Area */}
                       <div className="border-t border-slate-100 pt-6">
                           {activeRequest.status === 'NEGOTIATING' && (
                               <div className="bg-amber-50 border border-amber-200 rounded-2xl p-6">
                                   <h4 className="font-bold text-amber-800 mb-2">Step 1: Negotiate Fee</h4>
                                   <p className="text-sm text-amber-700 mb-4">Chat with the buyer to agree on a price, then enter it here to confirm.</p>
                                   <div className="flex gap-4">
                                       <div className="relative flex-1">
                                           <span className="absolute left-4 top-1/2 -translate-y-1/2 font-bold text-slate-500">$</span>
                                           <input 
                                             type="number" 
                                             value={feeInput}
                                             onChange={(e) => setFeeInput(e.target.value)}
                                             className="w-full pl-8 pr-4 py-3 rounded-xl border border-amber-200 outline-none focus:ring-2 focus:ring-amber-500 bg-white"
                                             placeholder="0.00"
                                           />
                                       </div>
                                       <button 
                                          onClick={handleUpdateFee}
                                          disabled={!feeInput}
                                          className="bg-amber-500 text-white px-6 py-3 rounded-xl font-bold hover:bg-amber-600 transition-colors disabled:opacity-50"
                                       >
                                           Confirm Fee
                                       </button>
                                   </div>
                               </div>
                           )}

                           {activeRequest.status === 'ACCEPTED' && (
                               <div className="bg-blue-50 border border-blue-200 rounded-2xl p-6 flex flex-col items-center text-center">
                                   <h4 className="font-bold text-blue-800 mb-2">Step 2: Pickup</h4>
                                   <p className="text-sm text-blue-700 mb-4">Proceed to the vendor location. Confirm when you have the item.</p>
                                   <button 
                                      onClick={() => handleStatusUpdate('PICKED_UP')}
                                      className="w-full bg-blue-600 text-white px-6 py-4 rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-500/20"
                                   >
                                       Confirm Pickup
                                   </button>
                               </div>
                           )}

                           {activeRequest.status === 'PICKED_UP' && (
                               <div className="bg-green-50 border border-green-200 rounded-2xl p-6 flex flex-col items-center text-center">
                                   <h4 className="font-bold text-green-800 mb-2">Step 3: Delivery</h4>
                                   <p className="text-sm text-green-700 mb-4">Head to the buyer. Collect cash (if applicable) and confirm delivery.</p>
