// Flatten the structure for search: "Town, City - Region"
export const getFlattenedLocations = (): string[] => {
  const flattened: string[] = [];

  GHANA_LOCATIONS.forEach(reg => {
    // Add Region Generic
    flattened.push(`${reg.region} Region`);

    reg.cities.forEach(city => {
      // Add City Generic if it's a major named city (not "Towns" or "Outskirts")
      if (city.name !== "Towns" && city.name !== "Outskirts") {
        flattened.push(`${city.name}, ${reg.region}`);
      }

      city.towns.forEach(town => {
        if (city.name === "Towns" || city.name === "Outskirts") {
           flattened.push(`${town}, ${reg.region}`);
        } else {
           flattened.push(`${town}, ${city.name} - ${reg.region}`);
        }
      });
    });
  });

  return flattened.sort();
};

import React, { useState, useEffect, useRef } from 'react';
import Icon from './Icon';
import { getFlattenedLocations } from '../constants/ghanaLocations';

interface LocationSelectProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  icon?: boolean;
}

const LocationSelect: React.FC<LocationSelectProps> = ({ 
  value, 
  onChange, 
  placeholder = "Select Location", 
  className = "",
  icon = true 
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState(value);
  const [options, setOptions] = useState<string[]>([]);
  const [filteredOptions, setFilteredOptions] = useState<string[]>([]);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Load locations on mount
  useEffect(() => {
    const allLocations = getFlattenedLocations();
    setOptions(allLocations);
    setFilteredOptions(allLocations.slice(0, 50)); // Initial Limit
  }, []);

  // Sync internal search term with prop value if prop changes externally
  useEffect(() => {
    setSearchTerm(value);
  }, [value]);

  // Handle outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        // If the user typed something but didn't select, keep it or revert?
        // Let's keep what they typed for free text flexibility, or revert to value.
        // For strict selection, we might want to revert, but classifieds often allow custom text.
        // We'll update the parent with the current search term on blur logic essentially.
        if (searchTerm !== value) {
            onChange(searchTerm);
        }
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [searchTerm, value, onChange]);

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const term = e.target.value;
    setSearchTerm(term);
    setIsOpen(true);
    onChange(term); // Allow typing

    if (term.trim() === '') {
      setFilteredOptions(options.slice(0, 50));
    } else {
      const lower = term.toLowerCase();
      const filtered = options.filter(opt => opt.toLowerCase().includes(lower)).slice(0, 50);
      setFilteredOptions(filtered);
    }
  };

  const handleSelect = (option: string) => {
    setSearchTerm(option);
    onChange(option);
    setIsOpen(false);
  };

  return (
    <div className={`relative ${className}`} ref={wrapperRef}>
      <div className="relative">
        <input 
          type="text" 
          value={searchTerm}
          onChange={handleSearch}
          onFocus={() => setIsOpen(true)}
          placeholder={placeholder}
          className={`w-full bg-slate-50 border border-slate-200 rounded-xl py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 font-medium ${icon ? 'pl-9 pr-8' : 'px-4'}`}
        />
        {icon && (
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
                <Icon name="mapPin" size={16} />
            </div>
        )}
        {searchTerm && (
            <button 
                onClick={() => { setSearchTerm(''); onChange(''); setIsOpen(true); }}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
            >
                <Icon name="x" size={14} />
            </button>
        )}
        {!searchTerm && (
             <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none">
                <Icon name="chevronRight" size={14} className="rotate-90" />
            </div>
        )}
      </div>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-xl border border-slate-100 max-h-60 overflow-y-auto z-50 animate-fade-in custom-scrollbar">
           {filteredOptions.length > 0 ? (
             filteredOptions.map((option, idx) => (
               <button
                 key={idx}
                 onClick={() => handleSelect(option)}
                 className="w-full text-left px-4 py-2.5 text-sm hover:bg-brand-50 hover:text-brand-700 text-slate-600 transition-colors border-b border-slate-50 last:border-0"
               >
                 {option}
               </button>
             ))
           ) : (
             <div className="p-4 text-center text-sm text-slate-400">
                No matching locations found.
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default LocationSelect;

import React, { useState, useRef } from 'react';
import Icon from './Icon';
import { analyzeImageForSearch } from '../services/ai';
import { CATEGORIES } from '../constants';
import { SearchFilters } from '../types';
import LocationSelect from './LocationSelect';

interface SmartSearchInputProps {
  placeholder?: string;
  className?: string;
  onSearch?: (query: string, filters?: SearchFilters) => void;
  variant?: 'simple' | 'hero';
}

const SmartSearchInput: React.FC<SmartSearchInputProps> = ({ 
  placeholder = "Search...", 
  className = "", 
  onSearch,
  variant = 'simple'
}) => {
  const [query, setQuery] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showFilters, setShowFilters] = useState(false);

  // Filter States
  const [filters, setFilters] = useState<SearchFilters>({
    categoryId: '',
    minPrice: '',
    maxPrice: '',
    location: '',
    condition: '',
    sortBy: 'newest'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleVoiceSearch = () => {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      alert("Voice search is not supported in your browser.");
      return;
    }

    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setQuery(transcript);
      if (onSearch) onSearch(transcript, filters);
    };

    recognition.start();
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
      alert("Image size is too large. Please upload an image under 5MB.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsAnalyzing(true);
    const reader = new FileReader();

    reader.onloadend = async () => {
      try {
        const base64String = (reader.result as string).split(',')[1];
        const result = await analyzeImageForSearch(base64String, file.type);
        setQuery(result);
        if (onSearch) onSearch(result, filters);
      } catch (error) {
        console.error(error);
        alert("Failed to analyze image. Please try again.");
      } finally {
        setIsAnalyzing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsDataURL(file);
  };

  const handleFilterChange = (field: keyof SearchFilters, value: string) => {
    setFilters(prev => ({ ...prev, [field]: value }));
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && onSearch) {
      onSearch(query, filters);
      setShowFilters(false);
    }
  };

  const handleApplyFilters = () => {
    if (onSearch) {
      onSearch(query, filters);
    }
    setShowFilters(false);
  };

  return (
    <div className={`relative ${className}`}>
      <div className="relative flex items-center z-20 group">
        {variant === 'simple' && (
          <div className="absolute left-3 text-slate-400 group-focus-within:text-brand-500 transition-colors pointer-events-none">
             <Icon name="search" size={18} />
          </div>
        )}

        <input 
          type="text" 
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          disabled={isAnalyzing}
          className={`w-full bg-slate-50/80 backdrop-blur-sm transition-all outline-none font-medium ${
             variant === 'simple' 
               ? 'pl-10 pr-32 py-3 rounded-2xl border border-slate-200 shadow-inner focus:bg-white focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500 focus:shadow-[0_0_15px_rgba(168,85,247,0.15)]' 
               : 'text-slate-800 placeholder-slate-400 pr-24'
          } ${isAnalyzing ? 'opacity-50 cursor-wait' : ''}`}
        />

        <div className={`absolute flex items-center gap-1 ${variant === 'simple' ? 'right-2' : 'right-0'}`}>
          {isAnalyzing ? (
            <div className="flex items-center gap-2 px-2">
              <span className="text-xs text-brand-600 font-medium whitespace-nowrap hidden sm:block">Thinking...</span>
              <div className="animate-spin text-brand-500">
                <Icon name="loader" size={20} />
              </div>
            </div>
          ) : (
            <>
               <button 
                 onClick={() => setShowFilters(!showFilters)}
                 className={`p-2 rounded-xl transition-all relative ${showFilters ? 'text-brand-600 bg-brand-50' : 'text-slate-400 hover:text-brand-600 hover:bg-white/80'}`}
                 title="Advanced Filters"
               >
                 <Icon name="sliders" size={18} />
               </button>
               <div className="w-px h-5 bg-slate-300 mx-0.5"></div>
               <button 
                 onClick={() => fileInputRef.current?.click()}
                 className="p-2 text-slate-400 hover:text-brand-600 hover:bg-white/80 rounded-xl transition-all"
                 title="Search by Image"
               >
                 <Icon name="camera" size={20} />
               </button>
               <button 
                 onClick={handleVoiceSearch}
                 className={`p-2 rounded-xl transition-all ${isListening ? 'text-red-500 bg-red-50 animate-pulse shadow-sm' : 'text-slate-400 hover:text-brand-600 hover:bg-white/80'}`}
                 title="Voice Search"
               >
                 <Icon name="mic" size={20} />
               </button>
            </>
          )}
        </div>

        <input 
          type="file" 
          ref={fileInputRef}
          onChange={handleImageUpload}
          accept="image/*"
          className="hidden" 
        />
      </div>

      {/* Advanced Filters Dropdown */}
      {showFilters && (
        <>
          {/* Overlay to close on click outside */}
          <div className="fixed inset-0 z-40" onClick={() => setShowFilters(false)}></div>

          <div className={`absolute top-full right-0 mt-3 w-full sm:w-[600px] bg-white/90 backdrop-blur-xl border border-white/60 rounded-3xl shadow-[0_20px_40px_-10px_rgba(147,51,234,0.15)] p-6 z-50 animate-fade-in ${variant === 'simple' ? 'left-0 sm:left-auto' : 'left-0'}`}>
            <div className="flex justify-between items-center mb-5">
               <h3 className="font-bold text-slate-800 flex items-center gap-2 font-display">
                 <Icon name="sliders" size={18} className="text-brand-600" /> Filter Options
               </h3>
               <button onClick={() => setFilters({ categoryId: '', minPrice: '', maxPrice: '', location: '', condition: '', sortBy: 'newest' })} className="text-xs font-semibold text-brand-600 hover:text-brand-700 hover:underline">
                 Reset All
               </button>
            </div>

            <div className="space-y-5">
              {/* Category */}
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Category</label>
                <div className="relative">
                    <select 
                    value={filters.categoryId} 
                    onChange={(e) => handleFilterChange('categoryId', e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 appearance-none font-medium"
                    >
                    <option value="">All Categories</option>
                    {CATEGORIES.map(cat => (
                        <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))}
                    </select>
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                        <Icon name="chevronRight" size={12} className="rotate-90" />
                    </div>
                </div>
              </div>

              {/* Price Range */}
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Price Range</label>
                <div className="flex gap-3">
                  <div className="relative w-1/2">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium">$</span>
                    <input 
                        type="number" 
                        placeholder="Min" 
                        value={filters.minPrice}
                        onChange={(e) => handleFilterChange('minPrice', e.target.value)}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-7 pr-3 py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 font-medium"
                    />
                  </div>
                  <div className="relative w-1/2">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium">$</span>
                    <input 
                        type="number" 
                        placeholder="Max" 
                        value={filters.maxPrice}
                        onChange={(e) => handleFilterChange('maxPrice', e.target.value)}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-7 pr-3 py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 font-medium"
                    />
                  </div>
                </div>
              </div>

              {/* Location & Condition Row */}
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Location</label>
                    <LocationSelect 
                        value={filters.location || ''}
                        onChange={(val) => handleFilterChange('location', val)}
                        placeholder="Region, City..."
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Condition</label>
                    <div className="relative">
                        <select 
                        value={filters.condition} 
                        onChange={(e) => handleFilterChange('condition', e.target.value)}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 appearance-none font-medium"
                        >
                        <option value="">Any</option>
                        <option value="new">New</option>
                        <option value="used-like-new">Like New</option>
                        <option value="used-good">Good</option>
                        <option value="used-fair">Fair</option>
                        </select>
                         <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                            <Icon name="chevronRight" size={12} className="rotate-90" />
                        </div>
                    </div>
                 </div>
              </div>

              <div className="pt-4 border-t border-slate-100">
                <button 
                  onClick={handleApplyFilters}
                  className="w-full bg-gradient-to-r from-brand-600 to-fuchsia-600 text-white font-bold py-3.5 rounded-xl hover:shadow-lg hover:shadow-fuchsia-500/25 transition-all transform hover:-translate-y-0.5"
                >
                  Apply Filters
                </button>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default SmartSearchInput;

import React, { useState, useRef } from 'react';
import { CATEGORIES } from '../constants';
import Icon from '../components/Icon';
import { Link } from 'react-router-dom';
import { generateAdDescription, suggestPriceRange, enhanceImage } from '../services/ai';
import LocationSelect from '../components/LocationSelect';

const PostAd: React.FC = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    categoryId: '',
    categoryName: '',
    title: '',
    price: '',
    condition: 'Used - Good',
    location: '',
    description: ''
  });
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiPriceSuggestion, setAiPriceSuggestion] = useState('');

  // Image handling
  const [images, setImages] = useState<string[]>([]);
  const [enhancingIndices, setEnhancingIndices] = useState<number[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleCategorySelect = (id: string, name: string) => {
    setFormData(prev => ({ ...prev, categoryId: id, categoryName: name }));
    setStep(2);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLocationChange = (value: string) => {
    setFormData(prev => ({ ...prev, location: value }));
  };

  const handleAiGenerate = async () => {
    if (!formData.title || !formData.categoryId) {
      alert("Please enter a title first!");
      return;
    }

    setIsAiLoading(true);
    try {
      const description = await generateAdDescription(formData.title, formData.categoryName, formData.condition);
      setFormData(prev => ({ ...prev, description }));

      const priceRange = await suggestPriceRange(formData.title, formData.categoryName, formData.condition);
      setAiPriceSuggestion(priceRange);
    } catch (error) {
      console.error(error);
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files = Array.from(e.target.files);

      files.forEach(file => {
        const reader = new FileReader();
        reader.onloadend = () => {
            if (reader.result) {
                setImages(prev => [...prev, reader.result as string]);
            }
        };
        // Explicitly cast to Blob to avoid TypeScript 'unknown' error
        reader.readAsDataURL(file as Blob);
      });
    }
  };

  const removeImage = (indexToRemove: number) => {
    setImages(prev => prev.filter((_, index) => index !== indexToRemove));
  };

  const handleEnhanceImage = async (index: number) => {
    if (enhancingIndices.includes(index)) return;

    const imageSrc = images[index];
    const matches = imageSrc.match(/^data:(.+);base64,(.+)$/);
    if (!matches) return;

    const mimeType = matches[1];
    const base64Data = matches[2];

    setEnhancingIndices(prev => [...prev, index]);

    try {
        const enhancedBase64 = await enhanceImage(base64Data, mimeType);
        const newImageSrc = `data:image/png;base64,${enhancedBase64}`;

        setImages(prev => {
            const newImages = [...prev];
            newImages[index] = newImageSrc;
            return newImages;
        });
    } catch (e) {
        alert("Failed to enhance image. Please try again.");
    } finally {
        setEnhancingIndices(prev => prev.filter(i => i !== index));
    }
  };

  return (
    <div className="container mx-auto px-4 pt-6 pb-12 max-w-4xl min-h-screen"> {/* Standardized padding with gap */}
      <div className="text-center mb-10">
        <h1 className="text-4xl font-bold text-slate-900 mb-3">Sell it fast.</h1>
        <p className="text-slate-500 text-lg">Use our AI tools to create the perfect listing in seconds.</p>
      </div>

      <div className="glass-card rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
        {/* Progress Bar */}
        <div className="bg-slate-50/50 border-b border-slate-100 p-6 flex justify-between items-center px-4 md:px-12">
           <div className={`flex items-center gap-2 ${step >= 1 ? 'text-brand-600 font-semibold' : 'text-slate-400'}`}>
              <span className={`w-8 h-8 rounded-full border-2 flex items-center justify-center text-sm ${step >= 1 ? 'border-brand-600 bg-brand-50' : 'border-current'}`}>1</span>
              <span className="hidden sm:inline">Category</span>
           </div>
           <div className="h-[2px] bg-slate-200 flex-1 mx-4">
             <div className="h-full bg-brand-500 transition-all duration-300" style={{ width: step >= 2 ? '50%' : step >= 3 ? '100%' : '0%' }}></div>
           </div>
           <div className={`flex items-center gap-2 ${step >= 2 ? 'text-brand-600 font-semibold' : 'text-slate-400'}`}>
              <span className={`w-8 h-8 rounded-full border-2 flex items-center justify-center text-sm ${step >= 2 ? 'border-brand-600 bg-brand-50' : 'border-current'}`}>2</span>
              <span className="hidden sm:inline">Details</span>
           </div>
           <div className="h-[2px] bg-slate-200 flex-1 mx-4">
             <div className="h-full bg-brand-500 transition-all duration-300" style={{ width: step >= 3 ? '100%' : '0%' }}></div>
           </div>
           <div className={`flex items-center gap-2 ${step >= 3 ? 'text-brand-600 font-semibold' : 'text-slate-400'}`}>
              <span className={`w-8 h-8 rounded-full border-2 flex items-center justify-center text-sm ${step >= 3 ? 'border-brand-600 bg-brand-50' : 'border-current'}`}>3</span>
              <span className="hidden sm:inline">Photos</span>
           </div>
        </div>

        <div className="p-6 md:p-10">
          {step === 1 && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 animate-fade-in">
              {CATEGORIES.map(cat => (
                <button
                  key={cat.id}
                  onClick={() => handleCategorySelect(cat.id, cat.name)}
                  className="group p-6 border border-slate-200 rounded-2xl hover:border-brand-500 hover:bg-brand-50/50 hover:shadow-lg transition-all flex flex-col items-center gap-4 text-center bg-white/60"
                >
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${cat.color} bg-opacity-20 group-hover:scale-110 transition-transform`}>
                    <img src={cat.icon3d} alt={cat.name} className="w-10 h-10 object-contain drop-shadow-sm" loading="lazy" />
                  </div>
                  <span className="text-sm font-semibold text-slate-700 group-hover:text-brand-700">{cat.name}</span>
                </button>
              ))}
            </div>
          )}

          {step === 2 && (
            <div className="space-y-8 max-w-2xl mx-auto animate-fade-in">
               <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2">What are you selling?</label>
                  <input 
                    type="text" 
                    name="title"
                    value={formData.title}
                    onChange={handleChange}
                    className="w-full border border-slate-300 rounded-xl p-4 focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all shadow-sm bg-white/60" 
                    placeholder="e.g. 2018 Toyota Camry, excellent condition" 
                  />
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2">Price</label>
                    <div className="relative">
                      <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500">$</span>
                      <input 
                        type="number" 
                        name="price"
                        value={formData.price}
                        onChange={handleChange}
                        className="w-full border border-slate-300 rounded-xl p-4 pl-8 focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all shadow-sm bg-white/60" 
                        placeholder="0.00" 
                      />
                    </div>
                    {aiPriceSuggestion && (
                      <p className="text-xs text-brand-600 mt-2 flex items-center gap-1">
                        <Icon name="coins" size={12} /> AI Suggested Range: {aiPriceSuggestion}
                      </p>
                    )}
                  </div>
                   <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2">Condition</label>
                    <select 
                      name="condition"
                      value={formData.condition}
                      onChange={handleChange}
                      className="w-full border border-slate-300 rounded-xl p-4 focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all shadow-sm bg-white/60"
                    >
                       <option>New</option>
                       <option>Used - Like New</option>
                       <option>Used - Good</option>
                       <option>Used - Fair</option>
                    </select>
                  </div>
               </div>

               <div>
                 <label className="block text-sm font-bold text-slate-700 mb-2">Location</label>
                 <LocationSelect 
                    value={formData.location}
                    onChange={handleLocationChange}
                    placeholder="Region, City or Town..."
                 />
               </div>

               <div className="relative">
                  <div className="flex justify-between items-end mb-2">
                    <label className="block text-sm font-bold text-slate-700">Description</label>
                    <button 
                      onClick={handleAiGenerate}
                      disabled={isAiLoading}
                      className="text-xs font-bold text-white bg-gradient-to-r from-violet-600 to-fuchsia-600 px-3 py-1.5 rounded-full hover:opacity-90 transition-opacity flex items-center gap-1 disabled:opacity-50"
                    >
                      {isAiLoading ? <Icon name="loader" size={12} className="animate-spin" /> : <Icon name="palette" size={12} />}
                      {isAiLoading ? 'Magic Working...' : 'Auto-Write with AI'}
                    </button>
                  </div>
                  <textarea 
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    rows={6} 
                    className="w-full border border-slate-300 rounded-xl p-4 focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all shadow-sm bg-white/60" 
                    placeholder="Describe your item... or let AI do it for you!"
                  ></textarea>
               </div>

               <div className="flex justify-between pt-6 border-t border-slate-100">
                  <button onClick={() => setStep(1)} className="text-slate-500 hover:text-slate-900 font-medium px-4 py-2">Back</button>
                  <button onClick={() => setStep(3)} className="bg-brand-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-brand-700 shadow-lg shadow-brand-500/20 transform hover:-translate-y-0.5 transition-all">Next: Photos</button>
               </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-8 max-w-4xl mx-auto animate-fade-in">
              <div 
                onClick={() => fileInputRef.current?.click()}
                className={`border-3 border-dashed border-slate-200 rounded-3xl hover:bg-slate-50 hover:border-brand-400 transition-all cursor-pointer group text-center ${images.length > 0 ? 'py-8 p-6' : 'p-16'}`}
              >
                 <div className="mx-auto w-16 h-16 bg-brand-50 text-brand-500 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform shadow-sm">
                    <Icon name="camera" size={24} />
                 </div>
                 <h3 className="font-bold text-xl text-slate-900 mb-2">
                    {images.length > 0 ? 'Add More Photos' : 'Upload Photos'}
                 </h3>
                 <p className="text-slate-500">Drag and drop or click to browse</p>
                 <p className="text-xs text-slate-400 mt-2 uppercase tracking-wider font-medium">Supports JPG, PNG</p>
                 <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    multiple 
                    accept="image/*"
                    onChange={handleImageUpload}
                 />
              </div>

              {/* Image Grid */}
              {images.length > 0 && (
                <div>
                    <h4 className="text-sm font-bold text-slate-700 mb-3">{images.length} Photos Selected</h4>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {images.map((img, index) => (
                            <div key={index} className="relative aspect-square rounded-2xl overflow-hidden group border border-slate-200 shadow-sm bg-slate-100">
                                <img src={img} alt={`Preview ${index}`} className="w-full h-full object-cover" />
                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors"></div>

                                {/* AI Enhance Button */}
                                <button 
                                    onClick={(e) => { e.stopPropagation(); handleEnhanceImage(index); }}
                                    className={`absolute top-2 left-2 p-1.5 rounded-full shadow-md transition-all z-20 ${enhancingIndices.includes(index) ? 'bg-white text-brand-500' : 'bg-white/90 text-brand-600 opacity-0 group-hover:opacity-100 hover:bg-white hover:scale-110'}`}
                                    title="Auto-Enhance Sharpness"
                                    disabled={enhancingIndices.includes(index)}
                                >
                                    {enhancingIndices.includes(index) ? (
                                        <Icon name="loader" size={16} className="animate-spin" />
                                    ) : (
                                        <Icon name="sparkles" size={16} />
                                    )}
                                </button>

                                <button 
                                    onClick={(e) => { e.stopPropagation(); removeImage(index); }}
                                    className="absolute top-2 right-2 p-1.5 bg-white text-red-500 rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-all hover:bg-red-50 hover:scale-110 z-20"
                                    title="Remove photo"
                                >
                                    <Icon name="x" size={16} />
                                </button>

                                {index === 0 && (
                                    <div className="absolute bottom-2 left-2 px-2 py-1 bg-black/60 backdrop-blur rounded text-[10px] text-white font-bold">
                                        COVER
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
              )}

               <div className="flex justify-between pt-8 border-t border-slate-100">
                  <button onClick={() => setStep(2)} className="text-slate-500 hover:text-slate-900 font-medium px-4 py-2">Back</button>
                  <Link to="/" className={`bg-brand-600 text-white px-10 py-4 rounded-xl font-bold hover:bg-brand-700 shadow-xl shadow-brand-500/30 transform hover:-translate-y-0.5 transition-all flex items-center gap-2 ${images.length === 0 ? 'opacity-50 pointer-events-none' : ''}`}>
                     <Icon name="check" size={20} /> Publish Ad
                  </Link>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PostAd;

