// Helper to get formatted search strings if needed elsewhere
export const getFlattenedLocations = (): string[] => {
  const flattened: string[] = [];
  GHANA_LOCATIONS.forEach(reg => {
    flattened.push(`${reg.region} Region`);
    reg.cities.forEach(city => {
      if (city.name !== "Other Towns") {
        flattened.push(`${city.name}, ${reg.region}`);
      }
      city.towns.forEach(town => {
        if (city.name === "Other Towns") {
           flattened.push(`${town}, ${reg.region}`);
        } else {
           flattened.push(`${town}, ${city.name} - ${reg.region}`);
        }
      });
    });
  });
  return flattened.sort();
};

import React, { useState, useEffect } from 'react';
import Icon from './Icon';
import { GHANA_LOCATIONS, LocationStructure } from '../constants/ghanaLocations';

interface LocationSelectProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  icon?: boolean;
}

const LocationSelect: React.FC<LocationSelectProps> = ({ 
  value, 
  onChange, 
  placeholder = "Select Location", 
  className = "",
  icon = true 
}) => {
  // State for the three dropdowns
  const [selectedRegion, setSelectedRegion] = useState('');
  const [selectedCity, setSelectedCity] = useState('');
  const [selectedTown, setSelectedTown] = useState('');

  // Derived options based on selections
  const [regionOptions, setRegionOptions] = useState<LocationStructure[]>([]);
  const [cityOptions, setCityOptions] = useState<any[]>([]);
  const [townOptions, setTownOptions] = useState<string[]>([]);

  // Initialize Region Options
  useEffect(() => {
    setRegionOptions(GHANA_LOCATIONS.sort((a, b) => a.region.localeCompare(b.region)));
  }, []);

  // Parse initial string value to populate dropdowns (e.g. "East Legon, Accra Metropolitan, Greater Accra")
  // Format expectation: "Town, City, Region" or "City, Region" or "Region"
  useEffect(() => {
    if (!value) {
        setSelectedRegion('');
        setSelectedCity('');
        setSelectedTown('');
        return;
    }

    // Try to parse the string roughly
    const parts = value.split(',').map(s => s.trim());

    // Reverse map check
    // This is simple parsing; for a real app, storing IDs would be better.
    // For now, we trust the flow of the component or just try to match.
    if (parts.length >= 1) {
        // Find if the last part is a region
        const regionName = parts[parts.length - 1];
        const regionData = GHANA_LOCATIONS.find(r => r.region === regionName);

        if (regionData) {
            setSelectedRegion(regionName);

            // If we have a city (second to last)
            if (parts.length >= 2) {
                const cityName = parts[parts.length - 2];
                // Check if city exists in region
                // Note: The formatted string in `ghanaLocations.ts` `getFlattenedLocations` uses " - " separator sometimes.
                // But this component constructs it with ", " separator.
                const cityData = regionData.cities.find(c => c.name === cityName);

                if (cityData) {
                    setSelectedCity(cityName);

                    // If we have a town (first part)
                    if (parts.length >= 3) {
                        const townName = parts[0];
                        if (cityData.towns.includes(townName)) {
                            setSelectedTown(townName);
                        }
                    }
                }
            }
        }
    }
  }, []); // Only on mount to avoid loops, or we handle updates carefully. 
  // Actually, we shouldn't rely on 'value' prop to drive internal state continuously 
  // unless we want external control. For simple forms, initial sync is usually enough.
  // If we want two-way binding that responds to external resets:
  useEffect(() => {
     if (value === '') {
        setSelectedRegion('');
        setSelectedCity('');
        setSelectedTown('');
     }
  }, [value]);


  // Update City Options when Region Changes
  useEffect(() => {
    const region = GHANA_LOCATIONS.find(r => r.region === selectedRegion);
    if (region) {
      setCityOptions(region.cities);
    } else {
      setCityOptions([]);
    }
  }, [selectedRegion]);

  // Update Town Options when City Changes
  useEffect(() => {
    const region = GHANA_LOCATIONS.find(r => r.region === selectedRegion);
    if (region) {
      const city = region.cities.find(c => c.name === selectedCity);
      if (city) {
        setTownOptions(city.towns.sort());
      } else {
        setTownOptions([]);
      }
    } else {
      setTownOptions([]);
    }
  }, [selectedCity, selectedRegion]);

  // Handle Changes
  const handleRegionChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newRegion = e.target.value;
    setSelectedRegion(newRegion);
    setSelectedCity('');
    setSelectedTown('');
    updateParent(newRegion, '', '');
  };

  const handleCityChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newCity = e.target.value;
    setSelectedCity(newCity);
    setSelectedTown('');
    updateParent(selectedRegion, newCity, '');
  };

  const handleTownChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newTown = e.target.value;
    setSelectedTown(newTown);
    updateParent(selectedRegion, selectedCity, newTown);
  };

  const updateParent = (r: string, c: string, t: string) => {
    // Construct the formatted string expected by the app
    let finalString = r;
    if (c) finalString = `${c}, ${r}`;
    if (t) finalString = `${t}, ${c}, ${r}`;

    // If nothing selected
    if (!r) finalString = '';

    onChange(finalString);
  };

  return (
    <div className={`flex flex-col gap-2 ${className}`}>

      {/* Region Select */}
      <div className="relative">
        <select
          value={selectedRegion}
          onChange={handleRegionChange}
          className={`w-full appearance-none bg-slate-50 border border-slate-200 rounded-xl py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 font-medium text-slate-700 ${icon ? 'pl-9 pr-8' : 'px-4'}`}
        >
          <option value="">Select Region</option>
          {regionOptions.map((r) => (
            <option key={r.region} value={r.region}>{r.region}</option>
          ))}
        </select>
        {icon && (
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
                <Icon name="mapPin" size={16} />
            </div>
        )}
        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
            <Icon name="chevronRight" size={14} className="rotate-90" />
        </div>
      </div>

      {/* City Select */}
      <div className="relative">
        <select
          value={selectedCity}
          onChange={handleCityChange}
          disabled={!selectedRegion}
          className={`w-full appearance-none bg-slate-50 border border-slate-200 rounded-xl py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 font-medium text-slate-700 ${icon ? 'pl-9 pr-8' : 'px-4'} disabled:opacity-50 disabled:cursor-not-allowed`}
        >
          <option value="">{selectedRegion ? "Select City / District" : "Select Region First"}</option>
          {cityOptions.map((c) => (
            <option key={c.name} value={c.name}>{c.name}</option>
          ))}
        </select>
        {icon && (
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
                <Icon name="building" size={16} />
            </div>
        )}
        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
            <Icon name="chevronRight" size={14} className="rotate-90" />
        </div>
      </div>

      {/* Town Select */}
      <div className="relative">
        <select
          value={selectedTown}
          onChange={handleTownChange}
          disabled={!selectedCity}
          className={`w-full appearance-none bg-slate-50 border border-slate-200 rounded-xl py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 font-medium text-slate-700 ${icon ? 'pl-9 pr-8' : 'px-4'} disabled:opacity-50 disabled:cursor-not-allowed`}
        >
          <option value="">{selectedCity ? "Select Town / Suburb" : "Select City First"}</option>
          {townOptions.map((t) => (
            <option key={t} value={t}>{t}</option>
          ))}
        </select>
        {icon && (
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
                <Icon name="mapPin" size={16} />
            </div>
        )}
        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
            <Icon name="chevronRight" size={14} className="rotate-90" />
        </div>
      </div>

    </div>
  );
};

export default LocationSelect;

import React, { useState, useRef } from 'react';
import Icon from './Icon';
import { analyzeImageForSearch } from '../services/ai';
import { CATEGORIES } from '../constants';
import { SearchFilters } from '../types';
import LocationSelect from './LocationSelect';

interface SmartSearchInputProps {
  placeholder?: string;
  className?: string;
  onSearch?: (query: string, filters?: SearchFilters) => void;
  variant?: 'simple' | 'hero';
}

const SmartSearchInput: React.FC<SmartSearchInputProps> = ({ 
  placeholder = "Search...", 
  className = "", 
  onSearch,
  variant = 'simple'
}) => {
  const [query, setQuery] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [showSort, setShowSort] = useState(false);

  // Filter States
  const [filters, setFilters] = useState<SearchFilters>({
    categoryId: '',
    minPrice: '',
    maxPrice: '',
    location: '',
    condition: '',
    sortBy: 'newest'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleVoiceSearch = () => {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      alert("Voice search is not supported in your browser.");
      return;
    }

    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setQuery(transcript);
      if (onSearch) onSearch(transcript, filters);
    };

    recognition.start();
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
      alert("Image size is too large. Please upload an image under 5MB.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setIsAnalyzing(true);
    const reader = new FileReader();

    reader.onloadend = async () => {
      try {
        const base64String = (reader.result as string).split(',')[1];
        const result = await analyzeImageForSearch(base64String, file.type);
        setQuery(result);
        if (onSearch) onSearch(result, filters);
      } catch (error) {
        console.error(error);
        alert("Failed to analyze image. Please try again.");
      } finally {
        setIsAnalyzing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsDataURL(file);
  };

  const handleFilterChange = (field: keyof SearchFilters, value: string) => {
    setFilters(prev => ({ ...prev, [field]: value }));
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && onSearch) {
      onSearch(query, filters);
      setShowFilters(false);
    }
  };

  const handleApplyFilters = () => {
    if (onSearch) {
      onSearch(query, filters);
    }
    setShowFilters(false);
  };

  const toggleFilters = () => {
    setShowFilters(!showFilters);
    if (showSort) setShowSort(false);
  };

  const toggleSort = () => {
    setShowSort(!showSort);
    if (showFilters) setShowFilters(false);
  };

  return (
    <div className={`relative ${className}`}>
      <div className="relative flex items-center z-20 group">
        {variant === 'simple' && (
          <div className="absolute left-3 text-slate-400 group-focus-within:text-brand-500 transition-colors pointer-events-none">
             <Icon name="search" size={18} />
          </div>
        )}

        <input 
          type="text" 
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          disabled={isAnalyzing}
          className={`w-full bg-slate-50/80 backdrop-blur-sm transition-all outline-none font-medium ${
             variant === 'simple' 
               ? 'pl-10 pr-32 py-3 rounded-2xl border border-slate-200 shadow-inner focus:bg-white focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500 focus:shadow-[0_0_15px_rgba(168,85,247,0.15)]' 
               : 'text-slate-800 placeholder-slate-400 pr-24'
          } ${isAnalyzing ? 'opacity-50 cursor-wait' : ''}`}
        />

        <div className={`absolute flex items-center gap-1 ${variant === 'simple' ? 'right-2' : 'right-0'}`}>
          {isAnalyzing ? (
            <div className="flex items-center gap-2 px-2">
              <span className="text-xs text-brand-600 font-medium whitespace-nowrap hidden sm:block">Thinking...</span>
              <div className="animate-spin text-brand-500">
                <Icon name="loader" size={20} />
              </div>
            </div>
          ) : (
            <>
               <button 
                 onClick={toggleSort}
                 className={`p-2 rounded-xl transition-all relative ${showSort ? 'text-brand-600 bg-brand-50' : 'text-slate-400 hover:text-brand-600 hover:bg-white/80'}`}
                 title="Sort Order"
               >
                 <Icon name="sort" size={18} />
               </button>
               <button 
                 onClick={toggleFilters}
                 className={`p-2 rounded-xl transition-all relative ${showFilters ? 'text-brand-600 bg-brand-50' : 'text-slate-400 hover:text-brand-600 hover:bg-white/80'}`}
                 title="Advanced Filters"
               >
                 <Icon name="sliders" size={18} />
               </button>
               <div className="w-px h-5 bg-slate-300 mx-0.5"></div>
               <button 
                 onClick={() => fileInputRef.current?.click()}
                 className="p-2 text-slate-400 hover:text-brand-600 hover:bg-white/80 rounded-xl transition-all"
                 title="Search by Image"
               >
                 <Icon name="camera" size={20} />
               </button>
               <button 
                 onClick={handleVoiceSearch}
                 className={`p-2 rounded-xl transition-all ${isListening ? 'text-red-500 bg-red-50 animate-pulse shadow-sm' : 'text-slate-400 hover:text-brand-600 hover:bg-white/80'}`}
                 title="Voice Search"
               >
                 <Icon name="mic" size={20} />
               </button>
            </>
          )}
        </div>

        <input 
          type="file" 
          ref={fileInputRef}
          onChange={handleImageUpload}
          accept="image/*"
          className="hidden" 
        />
      </div>

      {/* Sort Dropdown */}
      {showSort && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setShowSort(false)}></div>
          <div className="absolute top-full right-0 mt-3 w-48 bg-white/90 backdrop-blur-xl border border-white/60 rounded-2xl shadow-xl p-2 z-50 animate-fade-in flex flex-col gap-1">
             <div className="text-xs font-bold text-slate-400 px-3 py-2 uppercase tracking-wide">Sort Results By</div>
             {[
                 { label: 'Newest First', value: 'newest' },
                 { label: 'Price: Low to High', value: 'price_asc' },
                 { label: 'Price: High to Low', value: 'price_desc' },
                 { label: 'Relevance', value: 'relevance' }
             ].map(opt => (
                 <button
                    key={opt.value}
                    onClick={() => {
                        handleFilterChange('sortBy', opt.value);
                        setShowSort(false);
                        if (onSearch) onSearch(query, { ...filters, sortBy: opt.value });
                    }}
                    className={`text-left px-3 py-2 rounded-xl text-sm font-medium transition-colors ${filters.sortBy === opt.value ? 'bg-brand-50 text-brand-600' : 'text-slate-600 hover:bg-slate-50'}`}
                 >
                    {opt.label}
                 </button>
             ))}
          </div>
        </>
      )}

      {/* Advanced Filters Dropdown */}
      {showFilters && (
        <>
          {/* Overlay to close on click outside */}
          <div className="fixed inset-0 z-40" onClick={() => setShowFilters(false)}></div>

          <div className="absolute top-full left-0 mt-3 w-full bg-white/90 backdrop-blur-xl border border-white/60 rounded-3xl shadow-[0_20px_40px_-10px_rgba(147,51,234,0.15)] p-6 z-50 animate-fade-in">
            <div className="flex justify-between items-center mb-5">
               <h3 className="font-bold text-slate-800 flex items-center gap-2 font-display">
                 <Icon name="sliders" size={18} className="text-brand-600" /> Filter Options
               </h3>
               <button onClick={() => setFilters({ categoryId: '', minPrice: '', maxPrice: '', location: '', condition: '', sortBy: 'newest' })} className="text-xs font-semibold text-brand-600 hover:text-brand-700 hover:underline">
                 Reset All
               </button>
            </div>

            <div className="space-y-5">
              {/* Category */}
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Category</label>
                <div className="relative">
                    <select 
                    value={filters.categoryId} 
                    onChange={(e) => handleFilterChange('categoryId', e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-500/10 appearance-none font-medium"
                    >
                    <option value="">All Categories</option>
                    {CATEGORIES.map(cat => (
                        <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))}
                    </select>
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
