import { Logo } from './Logo';
import SmartSearchInput from './SmartSearchInput';
import { SearchFilters } from '../types';
import FuturisticBackground from './FuturisticBackground';
import { useAuth } from '../context/AuthContext';
import { useLocation as useAppLocation } from '../context/LocationContext';
import { CATEGORIES } from '../constants';
import AdBanner from './AdBanner';
import AdvertisementPopup from './AdvertisementPopup';

interface LayoutProps {
  children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const currentYear = new Date().getFullYear();
  const navigate = useNavigate();
  const location = useLocation();
  const { user, isAuthenticated } = useAuth();
  const { location: userLocData, refreshLocation, isLoading: isLocating } = useAppLocation();
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [isPaused, setIsPaused] = useState(false);

  // Duplicate categories for seamless infinite scroll
  const displayCategories = [...CATEGORIES, ...CATEGORIES];

  const handleManualLocate = () => {
    refreshLocation();
  };

  const scroll = (direction: 'left' | 'right') => {
    if (scrollContainerRef.current) {
        const { current } = scrollContainerRef;
        const scrollAmount = 300; 
        if (direction === 'left') {
            current.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
        } else {
            current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
        }
    }
  };

  // Auto-scroll logic
  useEffect(() => {
    // Scroll everywhere now
    const container = scrollContainerRef.current;
    if (!container) return;

    const interval = setInterval(() => {
      if (!isPaused && container) {
        // Continuous scroll - Speed increased
        // Moving 2 pixels per tick makes it visibly faster and smoother than 1px
        container.scrollLeft += 2;

        // Seamless Loop: Reset to 0 when we reach the start of the second set (halfway point)
        // Since the list is duplicated, the first half is identical to the second half.
        // We add a small buffer check to ensure we catch the crossover point
        if (container.scrollLeft >= (container.scrollWidth / 2) - 2) {
             container.scrollLeft = 0;
        }
      }
    }, 20); // 20ms interval (approx 50fps) for smooth motion

    return () => clearInterval(interval);
  }, [isPaused]);

  const handleSearch = (query: string, filters?: SearchFilters) => {
    console.log("Searching for:", query, filters);

    // Check filter overrides
    if (filters?.categoryId) {
