import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { CATEGORIES } from '../constants';
import ListingCard from '../components/ListingCard';
import { generateListings } from '../services/mockData';
import Icon from '../components/Icon';

const ITEMS_PER_BATCH = 40; // 8 rows * 5 columns = 40 items

const CategoryPage: React.FC = () => {
  const { categoryId } = useParams<{ categoryId: string }>();

  // Data State
  const [listings, setListings] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Filter State (Kept for future context integration if needed)
  const [selectedSubcats, setSelectedSubcats] = useState<string[]>([]);
  const [isSubcatOpen, setIsSubcatOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const category = CATEGORIES.find(c => c.id === categoryId);

  // Reset and load initial batch when category changes
  useEffect(() => {
    if (categoryId) {
      const initialListings = generateListings(categoryId, ITEMS_PER_BATCH, 0);
      setListings(initialListings);
      setSelectedSubcats([]); // Reset filters on category change
    }
  }, [categoryId]);

  // Handle click outside to close dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsSubcatOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLoadMore = () => {
    if (!categoryId) return;

    setIsLoading(true);
    // Simulate network delay for realistic feel
    setTimeout(() => {
      const nextBatch = generateListings(categoryId, ITEMS_PER_BATCH, listings.length);
      setListings(prev => [...prev, ...nextBatch]);
      setIsLoading(false);
    }, 800);
  };

  const toggleSubcat = (id: string) => {
    setSelectedSubcats(prev => 
      prev.includes(id) ? prev.filter(sid => sid !== id) : [...prev, id]
    );
  };

  const clearSubcats = () => setSelectedSubcats([]);

  if (!category) {
    return (
      <div className="container mx-auto px-4 py-20 text-center">
        <h2 className="text-2xl font-bold text-slate-800">Category not found</h2>
        <Link to="/" className="text-brand-600 mt-4 inline-block">Go Home</Link>
      </div>
    );
  }

  // NOTE: In a real app, we would filter 'listings' based on 'selectedSubcats' here.
  const displayListings = listings; 

  return (
    <div className="bg-brand-50 min-h-screen pb-8 pt-4">

      <div className="container mx-auto px-4">

        {/* Listings Section */}
        <div className="flex justify-between items-center mb-4 px-2 pt-2">
           <p className="text-slate-500 font-medium text-sm">Showing {displayListings.length} results</p>
        </div>

        {/* Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-5 gap-3 sm:gap-4">
           {displayListings.map(listing => (
              <ListingCard key={listing.id} listing={listing} />
           ))}
        </div>

        {/* Load More Button */}
        <div className="mt-12 flex justify-center">
           <button 
             onClick={handleLoadMore}
             disabled={isLoading}
             className="flex items-center gap-3 px-8 py-3.5 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 text-slate-700 font-bold shadow-sm hover:shadow-md transition-all disabled:opacity-70 disabled:cursor-not-allowed group active:scale-95"
           >
             {isLoading ? (
               <>
                 <span className="w-5 h-5 border-2 border-slate-300 border-t-brand-600 rounded-full animate-spin"></span>
                 Loading more items...
               </>
             ) : (
               <>
                 Load More Results
                 <Icon name="chevronRight" size={14} className="rotate-90 group-hover:translate-y-0.5 transition-transform" />
               </>
             )}
           </button>
        </div>
      </div>
    </div>
  );
};

