import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Listing } from '../types';
import { getUser } from '../services/mockData';
import { CATEGORIES } from '../constants';
import Icon from './Icon';
import { useLocation } from '../context/LocationContext';

interface ListingCardProps {
  listing: Listing;
}

const ListingCard: React.FC<ListingCardProps> = ({ listing }) => {
  const navigate = useNavigate();
  const seller = getUser(listing.sellerId);
  const category = CATEGORIES.find(c => c.id === listing.categoryId);
  const { convertPrice } = useLocation();
  const converted = convertPrice(listing.price);

  // Carousel Logic
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const images = listing.images && listing.images.length > 0 ? listing.images : [listing.imageUrl];

  // Auto-slide Logic
  useEffect(() => {
    if (images.length <= 1) return;

    const interval = setInterval(() => {
      setCurrentImageIndex((prev) => (prev + 1) % images.length);
    }, 8000); // Change every 8 seconds

    return () => clearInterval(interval);
  }, [currentImageIndex, images.length]); // Reset timer when image changes (manually or automatically)

  // Touch state for swipe
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);
  const minSwipeDistance = 50;

  const nextImage = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };

  const onTouchEnd = (e: React.TouchEvent) => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe || isRightSwipe) {
       // Prevent navigation when swiping
       e.preventDefault();
       e.stopPropagation();

       if (isLeftSwipe) {
          setCurrentImageIndex((prev) => (prev + 1) % images.length);
       } else {
          setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
       }
    }
  };

  const handleChat = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if(seller) {
        navigate(`/chat?to=${seller.id}`);
    } else {
        navigate('/signin');
    }
  };

  return (
    <div className="group block h-full select-none relative">
      <div className="relative h-full bg-white rounded-xl shadow-sm transition-all duration-500 hover:-translate-y-1 hover:shadow-[0_10px_25px_-5px_rgba(147,51,234,0.15)] flex flex-col isolate ring-1 ring-slate-100 hover:ring-brand-200">

        {/* Main Card Link - Absolute Overlay */}
        <Link to={`/listing/${listing.id}`} className="absolute inset-0 z-0 rounded-xl" aria-label={`View ${listing.title}`} />

        {/* Image Section - Rounded top corners only */}
        <div 
          className="relative aspect-[4/3] overflow-hidden bg-slate-100 rounded-t-xl group/image z-10 pointer-events-auto"
          onTouchStart={onTouchStart}
          onTouchMove={onTouchMove}
          onTouchEnd={onTouchEnd}
        >
           {/* Image Carousel */}
           {images.map((img, index) => (
              <img 
                key={index}
                src={img} 
                alt={`${listing.title} - ${index + 1}`}
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-700 ease-in-out group-hover:scale-110 ${index === currentImageIndex ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
                loading="lazy"
              />
           ))}

          {/* Gradient Overlay */}
          <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none"></div>

          {/* Navigation Arrows (Desktop) */}
          {images.length > 1 && (
            <>
              <button 
                onClick={prevImage}
                className="absolute left-1.5 top-1/2 -translate-y-1/2 w-6 h-6 bg-white/20 backdrop-blur-md hover:bg-white/90 rounded-full flex items-center justify-center text-white hover:text-slate-800 opacity-0 group-hover/image:opacity-100 transition-all duration-300 z-20 translate-x-2 group-hover/image:translate-x-0"
              >
                <Icon name="chevronRight" size={12} className="rotate-180" />
              </button>
              <button 
                onClick={nextImage}
                className="absolute right-1.5 top-1/2 -translate-y-1/2 w-6 h-6 bg-white/20 backdrop-blur-md hover:bg-white/90 rounded-full flex items-center justify-center text-white hover:text-slate-800 opacity-0 group-hover/image:opacity-100 transition-all duration-300 z-20 -translate-x-2 group-hover/image:translate-x-0"
              >
                <Icon name="chevronRight" size={12} />
              </button>
            </>
          )}

          {/* Pagination Dots */}
          {images.length > 1 && (
            <div className="absolute bottom-2 left-0 right-0 flex justify-center gap-1 z-20 pointer-events-none">
              {images.map((_, idx) => (
                <div 
                  key={idx} 
                  className={`w-1 h-1 rounded-full transition-all shadow-sm ${idx === currentImageIndex ? 'bg-white scale-125' : 'bg-white/40'}`}
                />
              ))}
            </div>
          )}

          {/* Floating Badges (Top Left) */}
          <div className="absolute top-2 left-2 flex flex-col gap-1 z-10 pointer-events-none">
             {listing.isFeatured && (
               <span className="px-1.5 py-0.5 rounded bg-white/95 backdrop-blur-md text-[9px] font-bold uppercase tracking-wider text-amber-600 shadow-sm flex items-center gap-1 border border-amber-100">
                 <Icon name="star" size={8} className="fill-amber-500 text-amber-500" /> Featured
               </span>
             )}
          </div>

          {/* Like Button (Top Right) */}
          <button 
            onClick={(e) => { e.preventDefault(); e.stopPropagation(); }}
            className="absolute top-2 right-2 w-7 h-7 flex items-center justify-center rounded-full bg-white/80 backdrop-blur-md hover:bg-white text-slate-500 hover:text-rose-500 transition-all duration-300 shadow-sm z-20 hover:scale-110 active:scale-95 group/btn"
          >
             <Icon name="heart" size={14} className="transition-transform group-active/btn:scale-90" />
          </button>

        </div>

        {/* Content Section - Rounded bottom corners only */}
        <div className="p-2.5 flex flex-col flex-grow relative bg-white rounded-b-xl z-10 pointer-events-none">

           {/* Top Row: Location & Date (Moved Location here) */}
           <div className="flex justify-between items-center mb-1">
              <div className="flex items-center gap-0.5 text-[10px] font-medium text-slate-500">
                 <Icon name="mapPin" size={10} className="text-slate-400" />
                 <span className="truncate max-w-[100px]">{listing.location}</span>
              </div>
              <span className="text-[9px] font-medium text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded-full">{listing.datePosted}</span>
           </div>

           {/* Title */}
           <h3 className="text-[13px] font-wix font-bold text-slate-800 leading-snug mb-1 line-clamp-2 group-hover:text-brand-600 transition-colors">
              {listing.title}
           </h3>

           {/* Footer: Price & Actions */}
           <div className="mt-auto pt-2 flex items-center justify-between border-t border-slate-50 pointer-events-auto">

              {/* Price - Standout (Label Removed) */}
              <div className="flex flex-col">
                  <div className="flex items-baseline gap-0.5 text-brand-600 group-hover:text-brand-700 transition-colors">
                    <span className="text-[10px] font-bold">{converted.symbol}</span>
                    <span className="text-lg font-wix font-extrabold tracking-tight">{converted.formatted}</span>
                  </div>
              </div>

              {/* Interactive Area */}
              <div className="flex items-center gap-2">
                  {/* Seller Avatar */}
                  <div className="relative group/avatar cursor-pointer z-30">
                    <div className="w-6 h-6 rounded-full border border-white shadow-sm overflow-hidden relative z-10 bg-slate-100 ring-1 ring-slate-100 group-hover:ring-brand-200 transition-all">
                       <img 
                          src={seller?.avatar || 'https://via.placeholder.com/40'} 
                          alt="Seller" 
                          className="w-full h-full object-cover" 
                       />
                    </div>
                    {seller?.verified && (
                       <div className="absolute -bottom-0.5 -right-0.5 z-20 bg-brand-500 text-white p-[1px] rounded-full border border-white">
                          <Icon name="check" size={4} />
                       </div>
                    )}

                    {/* Contact Pop-up Menu - REVEAL TO THE LEFT */}
                    <div className="absolute right-full top-1/2 -translate-y-1/2 mr-2 hidden group-hover/avatar:flex items-center gap-1 bg-white p-1 rounded-lg shadow-lg border border-slate-100 animate-fade-in origin-right whitespace-nowrap z-50">
                        {/* Chat */}
                        <button 
                            onClick={handleChat}
                            className="w-6 h-6 flex items-center justify-center rounded bg-brand-50 text-brand-600 hover:bg-brand-500 hover:text-white transition-colors border border-brand-100"
                            title="Chat"
                        >
                            <Icon name="messageCircle" size={12} />
                        </button>

                        {/* Phone */}
                        {seller?.socials.phone && (
                            <a 
                                href={`tel:${seller.socials.phone}`}
                                onClick={(e) => e.stopPropagation()}
                                className="w-6 h-6 flex items-center justify-center rounded bg-emerald-50 text-emerald-600 hover:bg-emerald-500 hover:text-white transition-colors border border-emerald-100"
                                title="Call"
                            >
                                <Icon name="phone" size={12} />
                            </a>
                        )}

                        {/* WhatsApp */}
                        {seller?.socials.whatsapp && (
                            <a 
                                href={`https://wa.me/${seller.socials.whatsapp}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="w-6 h-6 flex items-center justify-center rounded bg-[#f0fdf4] text-[#25D366] hover:bg-[#25D366] hover:text-white transition-colors border border-green-100"
                                title="WhatsApp"
                            >
                                <Icon name="whatsapp" size={12} />
                            </a>
                        )}

                        {/* Arrow nub */}
                        <div className="absolute top-1/2 -right-1 -translate-y-1/2 w-2 h-2 bg-white border-t border-r border-slate-100 rotate-45"></div>
                    </div>
                  </div>
              </div>
           </div>
        </div>

      </div>
    </div>
  );
};

